# NUMERICAL METHODS LIBRARY - ODE Solvers, Integration, Optimization
# ═══════════════════════════════════════════════════════════════════════════════

class NumericalMethods:
    """
    Comprehensive numerical methods library for UQFF calculations.
    
    Provides:
        - ODE Solvers: RK4, RK45, Adams-Bashforth, scipy.odeint wrapper
        - Integration: Trapezoidal, Simpson, Gaussian quadrature, scipy.quad wrapper
        - Optimization: Newton-Raphson, Bisection, scipy.fsolve wrapper
        - Linear Algebra: Matrix operations via scipy.linalg
        - Symbolic Math: Differentiation, integration via sympy
    
    Falls back to pure-numpy implementations if scipy/sympy unavailable.
    """
    
    # ─────────────────────────────────────────────────────────────────────────
    # ODE SOLVERS
    # ─────────────────────────────────────────────────────────────────────────
    
    @staticmethod
    def rk4_step(f: Callable, t: float, y: np.ndarray, h: float, *args) -> np.ndarray:
        """
        Single step of 4th-order Runge-Kutta method.
        
        Args:
            f: Function dy/dt = f(t, y, *args)
            t: Current time
            y: Current state vector
            h: Step size
            *args: Additional arguments passed to f
            
        Returns:
            y_next: State at t + h
        """
        k1 = h * np.asarray(f(t, y, *args))
        k2 = h * np.asarray(f(t + h/2, y + k1/2, *args))
        k3 = h * np.asarray(f(t + h/2, y + k2/2, *args))
        k4 = h * np.asarray(f(t + h, y + k3, *args))
        return y + (k1 + 2*k2 + 2*k3 + k4) / 6
    
    @staticmethod
    def rk4_solve(f: Callable, t_span: Tuple[float, float], y0: np.ndarray,
                  n_steps: int = 1000, *args) -> Tuple[np.ndarray, np.ndarray]:
        """
        Solve ODE using 4th-order Runge-Kutta method.
        
        Args:
            f: Function dy/dt = f(t, y, *args)
            t_span: (t_start, t_end)
            y0: Initial state vector
            n_steps: Number of integration steps
            *args: Additional arguments passed to f
            
        Returns:
            t: Time array
            y: Solution array (n_steps x len(y0))
        """
        t = np.linspace(t_span[0], t_span[1], n_steps)
        h = (t_span[1] - t_span[0]) / (n_steps - 1)
        y = np.zeros((n_steps, len(np.atleast_1d(y0))))
        y[0] = np.atleast_1d(y0)
        
        for i in range(n_steps - 1):
            y[i+1] = NumericalMethods.rk4_step(f, t[i], y[i], h, *args)
        
        return t, y
    
    @staticmethod
    def rk45_adaptive(f: Callable, t_span: Tuple[float, float], y0: np.ndarray,
                      rtol: float = 1e-6, atol: float = 1e-9, max_steps: int = 10000,
                      *args) -> Tuple[np.ndarray, np.ndarray]:
        """
        Adaptive RK4(5) Dormand-Prince method (like scipy.solve_ivp RK45).
        
        Uses scipy if available, otherwise falls back to fixed-step RK4.
        """
        if SCIPY_AVAILABLE:
            from scipy.integrate import solve_ivp
            sol = solve_ivp(lambda t, y: f(t, y, *args), t_span, np.atleast_1d(y0),
                           method='RK45', rtol=rtol, atol=atol, max_step=max_steps)
            return sol.t, sol.y.T
        else:
            # Fallback to fixed-step RK4
            return NumericalMethods.rk4_solve(f, t_span, y0, n_steps=1000, *args)
    
    @staticmethod
    def euler_step(f: Callable, t: float, y: np.ndarray, h: float, *args) -> np.ndarray:
        """
        Single step of Forward Euler method.
        
        Args:
            f: Function dy/dt = f(t, y, *args)
            t: Current time
            y: Current state vector
            h: Step size
            *args: Additional arguments passed to f
            
        Returns:
            y_next: State at t + h
        """
        return y + h * np.asarray(f(t, y, *args))
    
    @staticmethod
    def euler_solve(f: Callable, t_span: Tuple[float, float], y0: np.ndarray,
                    n_steps: int = 1000, *args) -> Tuple[np.ndarray, np.ndarray]:
        """
        Solve ODE using Forward Euler method.
        
        Simple first-order method. Less accurate than RK4 but faster per step.
        Useful for stiff systems or initial exploration.
        
        Args:
            f: Function dy/dt = f(t, y, *args)
            t_span: (t_start, t_end)
            y0: Initial state vector
            n_steps: Number of integration steps
            *args: Additional arguments passed to f
            
        Returns:
            t: Time array
            y: Solution array (n_steps x len(y0))
        """
        t = np.linspace(t_span[0], t_span[1], n_steps)
        h = (t_span[1] - t_span[0]) / (n_steps - 1)
        y = np.zeros((n_steps, len(np.atleast_1d(y0))))
        y[0] = np.atleast_1d(y0)
        
        for i in range(n_steps - 1):
            y[i+1] = NumericalMethods.euler_step(f, t[i], y[i], h, *args)
        
        return t, y
    
    @staticmethod
    def euler_implicit(f: Callable, t_span: Tuple[float, float], y0: np.ndarray,
                       n_steps: int = 1000, tol: float = 1e-8, *args) -> Tuple[np.ndarray, np.ndarray]:
        """
        Solve ODE using Backward (Implicit) Euler method.
        
        More stable than Forward Euler for stiff systems.
        Uses Newton-Raphson iteration at each step.
        
        Args:
            f: Function dy/dt = f(t, y, *args)
            t_span: (t_start, t_end)
            y0: Initial state vector
            n_steps: Number of integration steps
            tol: Newton iteration tolerance
            *args: Additional arguments passed to f
            
        Returns:
            t: Time array
            y: Solution array
        """
        t = np.linspace(t_span[0], t_span[1], n_steps)
        h = (t_span[1] - t_span[0]) / (n_steps - 1)
        y = np.zeros((n_steps, len(np.atleast_1d(y0))))
        y[0] = np.atleast_1d(y0)
        
        for i in range(n_steps - 1):
            # Newton iteration to solve y_{n+1} = y_n + h*f(t_{n+1}, y_{n+1})
            y_next = y[i].copy()  # Initial guess: forward Euler
            for _ in range(20):  # Max Newton iterations
                residual = y_next - y[i] - h * np.asarray(f(t[i+1], y_next, *args))
                if np.max(np.abs(residual)) < tol:
                    break
                # Simple fixed-point iteration (works for non-stiff)
                y_next = y[i] + h * np.asarray(f(t[i+1], y_next, *args))
            y[i+1] = y_next
        
        return t, y
    
    @staticmethod
    def adams_bashforth_4(f: Callable, t_span: Tuple[float, float], y0: np.ndarray,
                          n_steps: int = 1000, *args) -> Tuple[np.ndarray, np.ndarray]:
        """
        4th-order Adams-Bashforth linear multistep method.
        
        More efficient than RK4 for smooth problems (reuses function evaluations).
        Uses RK4 for initial bootstrap steps.
        """
        t = np.linspace(t_span[0], t_span[1], n_steps)
        h = (t_span[1] - t_span[0]) / (n_steps - 1)
        y = np.zeros((n_steps, len(np.atleast_1d(y0))))
        y[0] = np.atleast_1d(y0)
        
        # Bootstrap with RK4 for first 4 steps
        f_history = [np.asarray(f(t[0], y[0], *args))]
        for i in range(min(3, n_steps - 1)):
            y[i+1] = NumericalMethods.rk4_step(f, t[i], y[i], h, *args)
            f_history.append(np.asarray(f(t[i+1], y[i+1], *args)))
        
        # Adams-Bashforth 4th order: y_{n+1} = y_n + h/24 * (55*f_n - 59*f_{n-1} + 37*f_{n-2} - 9*f_{n-3})
        for i in range(3, n_steps - 1):
            y[i+1] = y[i] + h/24 * (
                55 * f_history[-1] - 59 * f_history[-2] + 
                37 * f_history[-3] - 9 * f_history[-4]
            )
            f_history.append(np.asarray(f(t[i+1], y[i+1], *args)))
            f_history.pop(0)  # Keep only last 4
        
        return t, y
    
    # ─────────────────────────────────────────────────────────────────────────
    # SYMPLECTIC INTEGRATORS (Energy-Conserving for N-Body/Orbital Mechanics)
    # ─────────────────────────────────────────────────────────────────────────
    
    @staticmethod
    def leapfrog_step(x: np.ndarray, v: np.ndarray, a_func: Callable, 
                      dt: float, *args) -> Tuple[np.ndarray, np.ndarray]:
        """
        Single step of Leapfrog (Störmer-Verlet) symplectic integrator.
        
        CRITICAL for UQFF: Preserves phase-space volume (Liouville's theorem).
        Energy conservation for Hamiltonian systems over long timescales.
        
        Args:
            x: Position vector(s)
            v: Velocity vector(s)
            a_func: Acceleration function a = a_func(x, *args)
            dt: Time step
            *args: Additional arguments to a_func
            
        Returns:
            (x_new, v_new): Updated position and velocity
        """
        x = np.atleast_1d(x)
        v = np.atleast_1d(v)
        
        # Kick-Drift-Kick (KDK) form
        a = np.asarray(a_func(x, *args))
        v_half = v + 0.5 * dt * a          # Half kick
        x_new = x + dt * v_half             # Drift
        a_new = np.asarray(a_func(x_new, *args))
        v_new = v_half + 0.5 * dt * a_new   # Half kick
        
        return x_new, v_new
    
    @staticmethod
    def leapfrog_solve(x0: np.ndarray, v0: np.ndarray, a_func: Callable,
                       t_span: Tuple[float, float], n_steps: int = 1000,
                       *args) -> Tuple[np.ndarray, np.ndarray, np.ndarray]:
        """
        Solve 2nd-order ODE using Leapfrog method.
        
        UQFF Application: Orbital mechanics, N-body gravity simulations,
        planetary system evolution, binary star dynamics.
        
        Args:
            x0: Initial position
            v0: Initial velocity
            a_func: Acceleration function a = a_func(x, *args)
            t_span: (t_start, t_end)
            n_steps: Number of integration steps
            *args: Additional arguments to a_func
            
        Returns:
            t: Time array
            x: Position array (n_steps x dim)
            v: Velocity array (n_steps x dim)
        """
        t = np.linspace(t_span[0], t_span[1], n_steps)
        dt = (t_span[1] - t_span[0]) / (n_steps - 1)
        
        x0 = np.atleast_1d(x0)
        v0 = np.atleast_1d(v0)
        
        x = np.zeros((n_steps, len(x0)))
        v = np.zeros((n_steps, len(v0)))
        x[0], v[0] = x0, v0
        
        for i in range(n_steps - 1):
            x[i+1], v[i+1] = NumericalMethods.leapfrog_step(x[i], v[i], a_func, dt, *args)
        
        return t, x, v
    
    @staticmethod
    def velocity_verlet_step(x: np.ndarray, v: np.ndarray, a: np.ndarray,
                             a_func: Callable, dt: float, *args) -> Tuple[np.ndarray, np.ndarray, np.ndarray]:
        """
        Single step of Velocity-Verlet (optimized for N-body).
        
        Returns current acceleration for reuse in next step (efficiency).
        
        Args:
            x: Position
            v: Velocity
            a: Current acceleration (from previous step or initial)
            a_func: Acceleration function a = a_func(x, *args)
            dt: Time step
            *args: Additional arguments
            
        Returns:
            (x_new, v_new, a_new)
        """
        x = np.atleast_1d(x)
        v = np.atleast_1d(v)
        a = np.atleast_1d(a)
        
        x_new = x + v * dt + 0.5 * a * dt**2
        a_new = np.asarray(a_func(x_new, *args))
        v_new = v + 0.5 * (a + a_new) * dt
        
        return x_new, v_new, a_new
    
    @staticmethod
    def velocity_verlet_solve(x0: np.ndarray, v0: np.ndarray, a_func: Callable,
                              t_span: Tuple[float, float], n_steps: int = 1000,
                              *args) -> Tuple[np.ndarray, np.ndarray, np.ndarray]:
        """
        Solve 2nd-order ODE using Velocity-Verlet.
        
        Mathematically equivalent to Leapfrog but with better velocity accuracy
        at output times. Preferred for N-body gravity simulations.
        
        Returns:
            t, x, v arrays
        """
        t = np.linspace(t_span[0], t_span[1], n_steps)
        dt = (t_span[1] - t_span[0]) / (n_steps - 1)
        
        x0 = np.atleast_1d(x0)
        v0 = np.atleast_1d(v0)
        
        x = np.zeros((n_steps, len(x0)))
        v = np.zeros((n_steps, len(v0)))
        x[0], v[0] = x0, v0
        
        # Initial acceleration
        a = np.asarray(a_func(x0, *args))
        
        for i in range(n_steps - 1):
            x[i+1], v[i+1], a = NumericalMethods.velocity_verlet_step(
                x[i], v[i], a, a_func, dt, *args)
        
        return t, x, v
    
    @staticmethod
    def yoshida4_step(x: np.ndarray, v: np.ndarray, a_func: Callable,
                      dt: float, *args) -> Tuple[np.ndarray, np.ndarray]:
        """
        Single step of 4th-order Yoshida symplectic integrator.
        
        Higher order symplectic method for long-term orbital stability.
        Used in UQFF for high-precision planetary ephemerides.
        
        Reference: Yoshida (1990), Phys. Lett. A 150, 262
        """
        # Yoshida 4th order coefficients
        w0 = -2**(1/3) / (2 - 2**(1/3))
        w1 = 1 / (2 - 2**(1/3))
        c1 = c4 = w1 / 2
        c2 = c3 = (w0 + w1) / 2
        d1 = d3 = w1
        d2 = w0
        
        x = np.atleast_1d(x)
        v = np.atleast_1d(v)
        
        # Symplectic chain: x-v-x-v-x-v-x
        x = x + c1 * dt * v
        v = v + d1 * dt * np.asarray(a_func(x, *args))
        x = x + c2 * dt * v
        v = v + d2 * dt * np.asarray(a_func(x, *args))
        x = x + c3 * dt * v
        v = v + d3 * dt * np.asarray(a_func(x, *args))
        x = x + c4 * dt * v
        
        return x, v
    
    @staticmethod
    def yoshida4_solve(x0: np.ndarray, v0: np.ndarray, a_func: Callable,
                       t_span: Tuple[float, float], n_steps: int = 1000,
                       *args) -> Tuple[np.ndarray, np.ndarray, np.ndarray]:
        """
        4th-order Yoshida symplectic integrator for orbital mechanics.
        
        UQFF Application: High-precision long-term orbital evolution,
        galactic dynamics, UQFF gravity field trajectories.
        
        Returns:
            t, x, v arrays
        """
        t = np.linspace(t_span[0], t_span[1], n_steps)
        dt = (t_span[1] - t_span[0]) / (n_steps - 1)
        
        x0 = np.atleast_1d(x0)
        v0 = np.atleast_1d(v0)
        
        x = np.zeros((n_steps, len(x0)))
        v = np.zeros((n_steps, len(v0)))
        x[0], v[0] = x0, v0
        
        for i in range(n_steps - 1):
            x[i+1], v[i+1] = NumericalMethods.yoshida4_step(x[i], v[i], a_func, dt, *args)
        
        return t, x, v
    
    @staticmethod
    def compute_orbital_energy(x: np.ndarray, v: np.ndarray, m: float, 
                               M: float, G: float = 6.674e-11) -> float:
        """
        Compute total orbital energy (kinetic + potential).
        
        For symplectic integrator validation: E should remain constant.
        
        Args:
            x: Position vector
            v: Velocity vector
            m: Orbiting mass
            M: Central mass
            G: Gravitational constant
            
        Returns:
            Total energy (negative for bound orbits)
        """
        x = np.atleast_1d(x)
        v = np.atleast_1d(v)
        r = np.linalg.norm(x)
        v_mag = np.linalg.norm(v)
        
        kinetic = 0.5 * m * v_mag**2
        potential = -G * M * m / r
        
        return kinetic + potential
    
    @staticmethod
    def compute_angular_momentum(x: np.ndarray, v: np.ndarray, m: float) -> np.ndarray:
        """
        Compute angular momentum vector L = m * (x × v).
        
        For symplectic integrator validation: L should remain constant.
        """
        x = np.atleast_1d(x)
        v = np.atleast_1d(v)
        
        if len(x) == 2:
            # 2D: return scalar Lz
            return m * (x[0] * v[1] - x[1] * v[0])
        elif len(x) == 3:
            return m * np.cross(x, v)
        else:
            raise ValueError("Position must be 2D or 3D")
    
    @staticmethod
    def odeint(f: Callable, y0: np.ndarray, t: np.ndarray, *args) -> np.ndarray:
        """
        scipy.odeint wrapper with fallback to RK4.
        
        Args:
            f: Function dy/dt = f(y, t, *args) - NOTE: scipy uses (y, t) order!
            y0: Initial state
            t: Time array
            *args: Additional arguments
            
        Returns:
            y: Solution array
        """
        if SCIPY_AVAILABLE:
            from scipy.integrate import odeint as scipy_odeint
            return scipy_odeint(f, y0, t, args=args)
        else:
            # Convert to (t, y) order for our RK4
            def f_reorder(t, y, *a):
                return f(y, t, *a)
            _, y = NumericalMethods.rk4_solve(f_reorder, (t[0], t[-1]), y0, len(t), *args)
            return y
    
    # ─────────────────────────────────────────────────────────────────────────
    # NUMERICAL INTEGRATION
    # ─────────────────────────────────────────────────────────────────────────
    
    @staticmethod
    def trapezoidal(f: Callable, a: float, b: float, n: int = 1000) -> float:
        """Trapezoidal rule integration."""
        x = np.linspace(a, b, n)
        y = np.array([f(xi) for xi in x])
        return np.trapz(y, x)
    
    @staticmethod
    def simpson(f: Callable, a: float, b: float, n: int = 1000) -> float:
        """Simpson's rule integration (n must be even)."""
        if n % 2 == 1:
            n += 1
        x = np.linspace(a, b, n + 1)
        y = np.array([f(xi) for xi in x])
        h = (b - a) / n
        return h/3 * (y[0] + 4*np.sum(y[1:-1:2]) + 2*np.sum(y[2:-2:2]) + y[-1])
    
    @staticmethod
    def gaussian_quadrature(f: Callable, a: float, b: float, n: int = 5) -> float:
        """Gauss-Legendre quadrature (high accuracy for smooth functions)."""
        if SCIPY_AVAILABLE:
            from scipy.integrate import fixed_quad
            result, _ = fixed_quad(f, a, b, n=n)
            return result
        else:
            # Fallback to Simpson
            return NumericalMethods.simpson(f, a, b, n=100)
    
    @staticmethod
    def quad(f: Callable, a: float, b: float, **kwargs) -> Tuple[float, float]:
        """
        Adaptive quadrature integration (scipy.integrate.quad wrapper).
        
        Returns:
            (integral, error_estimate)
        """
        if SCIPY_AVAILABLE:
            from scipy.integrate import quad as scipy_quad
            return scipy_quad(f, a, b, **kwargs)
        else:
            result = NumericalMethods.simpson(f, a, b, n=10000)
            return (result, abs(result) * 1e-6)  # Estimate error
    
    @staticmethod
    def dblquad(f: Callable, a: float, b: float, gfun: Callable, hfun: Callable,
                **kwargs) -> Tuple[float, float]:
        """Double integration over region. scipy.integrate.dblquad wrapper."""
        if SCIPY_AVAILABLE:
            from scipy.integrate import dblquad as scipy_dblquad
            return scipy_dblquad(f, a, b, gfun, hfun, **kwargs)
        else:
            # Fallback: nested Simpson
            def inner(y):
                return NumericalMethods.simpson(lambda x: f(x, y), gfun(y), hfun(y))
            result = NumericalMethods.simpson(inner, a, b)
            return (result, abs(result) * 1e-5)
    
    # ─────────────────────────────────────────────────────────────────────────
    # NONLINEAR EQUATION SOLVERS
    # ─────────────────────────────────────────────────────────────────────────
    
    @staticmethod
    def newton_raphson(f: Callable, x0: float, fprime: Callable = None,
                       tol: float = 1e-10, maxiter: int = 100) -> Tuple[float, bool]:
        """
        Newton-Raphson root finding.
        
        Args:
            f: Function to find root of
            x0: Initial guess
            fprime: Derivative (if None, uses numerical differentiation)
            tol: Tolerance
            maxiter: Maximum iterations
            
        Returns:
            (root, converged)
        """
        x = x0
        for _ in range(maxiter):
            fx = f(x)
            if abs(fx) < tol:
                return (x, True)
            
            if fprime is not None:
                dfx = fprime(x)
            else:
                # Numerical derivative
                h = 1e-8 * max(1.0, abs(x))
                dfx = (f(x + h) - f(x - h)) / (2 * h)
            
            if abs(dfx) < 1e-15:
                return (x, False)  # Zero derivative
            
            x = x - fx / dfx
        
        return (x, abs(f(x)) < tol)
    
    @staticmethod
    def bisection(f: Callable, a: float, b: float, tol: float = 1e-10,
                  maxiter: int = 100) -> Tuple[float, bool]:
        """Bisection method for root finding (guaranteed convergence if f(a)*f(b) < 0)."""
        fa, fb = f(a), f(b)
        if fa * fb > 0:
            return ((a + b) / 2, False)  # No guaranteed root
        
        for _ in range(maxiter):
            c = (a + b) / 2
            fc = f(c)
            
            if abs(fc) < tol or (b - a) / 2 < tol:
                return (c, True)
            
            if fa * fc < 0:
                b, fb = c, fc
            else:
                a, fa = c, fc
        
        return ((a + b) / 2, False)
    
    @staticmethod
    def brentq(f: Callable, a: float, b: float, **kwargs) -> float:
        """Brent's method (scipy.optimize.brentq wrapper)."""
        if SCIPY_AVAILABLE:
            from scipy.optimize import brentq as scipy_brentq
            return scipy_brentq(f, a, b, **kwargs)
        else:
            result, _ = NumericalMethods.bisection(f, a, b)
            return result
    
    @staticmethod
    def fsolve(f: Callable, x0: np.ndarray, **kwargs) -> np.ndarray:
        """Solve nonlinear system F(x) = 0 (scipy.optimize.fsolve wrapper)."""
        if SCIPY_AVAILABLE:
            from scipy.optimize import fsolve as scipy_fsolve
            return scipy_fsolve(f, x0, **kwargs)
        else:
            # Fallback: Newton-Raphson for single variable
            x0 = np.atleast_1d(x0)
            if len(x0) == 1:
                result, _ = NumericalMethods.newton_raphson(lambda x: f([x])[0], x0[0])
                return np.array([result])
            else:
                raise NotImplementedError("Multi-variable fsolve requires scipy")
    
    @staticmethod
    def root(f: Callable, x0: np.ndarray, method: str = 'hybr', **kwargs) -> dict:
        """General root finding (scipy.optimize.root wrapper)."""
        if SCIPY_AVAILABLE:
            from scipy.optimize import root as scipy_root
            return scipy_root(f, x0, method=method, **kwargs)
        else:
            x = NumericalMethods.fsolve(f, x0)
            return {'x': x, 'success': True, 'message': 'Fallback solver used'}
    
    # ─────────────────────────────────────────────────────────────────────────
    # LINEAR ALGEBRA
    # ─────────────────────────────────────────────────────────────────────────
    
    @staticmethod
    def solve_linear(A: np.ndarray, b: np.ndarray) -> np.ndarray:
        """Solve Ax = b."""
        if SCIPY_AVAILABLE:
            from scipy.linalg import solve
            return solve(A, b)
        else:
            return np.linalg.solve(A, b)
    
    @staticmethod
    def inv(A: np.ndarray) -> np.ndarray:
        """Matrix inverse."""
        if SCIPY_AVAILABLE:
            from scipy.linalg import inv
            return inv(A)
        else:
            return np.linalg.inv(A)
    
    @staticmethod
    def eig(A: np.ndarray) -> Tuple[np.ndarray, np.ndarray]:
        """Eigenvalues and eigenvectors."""
        if SCIPY_AVAILABLE:
            from scipy.linalg import eig
            return eig(A)
        else:
            return np.linalg.eig(A)
    
    @staticmethod
    def svd(A: np.ndarray) -> Tuple[np.ndarray, np.ndarray, np.ndarray]:
        """Singular Value Decomposition."""
        if SCIPY_AVAILABLE:
            from scipy.linalg import svd
            return svd(A)
        else:
            return np.linalg.svd(A)
    
    # ─────────────────────────────────────────────────────────────────────────
    # SYMBOLIC MATH (via sympy)
    # ─────────────────────────────────────────────────────────────────────────
    
    @staticmethod
    def symbolic_diff(expr_str: str, var: str = 'x') -> str:
        """Symbolic differentiation."""
        if SYMPY_AVAILABLE:
            x = symbols(var)
            expr = sympy.sympify(expr_str)
            return str(diff(expr, x))
        else:
            return f"d/d{var}({expr_str}) [sympy required for symbolic diff]"
    
    @staticmethod
    def symbolic_integrate(expr_str: str, var: str = 'x',
                           limits: Tuple[float, float] = None) -> str:
        """Symbolic integration."""
        if SYMPY_AVAILABLE:
            x = symbols(var)
            expr = sympy.sympify(expr_str)
            if limits:
                return str(sym_integrate(expr, (x, limits[0], limits[1])))
            else:
                return str(sym_integrate(expr, x))
        else:
            return f"∫({expr_str})d{var} [sympy required for symbolic integration]"
    
    @staticmethod
    def symbolic_solve(eq_str: str, var: str = 'x') -> list:
        """Solve algebraic equation symbolically."""
        if SYMPY_AVAILABLE:
            x = symbols(var)
            # Parse equation: "x**2 - 4 = 0" or "x**2 - 4"
            if '=' in eq_str:
                lhs, rhs = eq_str.split('=')
                eq = Eq(sympy.sympify(lhs.strip()), sympy.sympify(rhs.strip()))
            else:
                eq = sympy.sympify(eq_str)
            solutions = sym_solve(eq, x)
            return [str(s) for s in solutions]
        else:
            return [f"[sympy required to solve {eq_str}]"]
    
    @staticmethod
    def symbolic_simplify(expr_str: str) -> str:
        """Simplify expression."""
        if SYMPY_AVAILABLE:
            return str(simplify(sympy.sympify(expr_str)))
        else:
            return expr_str
    
    @staticmethod
    def lambdify_expr(expr_str: str, vars: List[str] = ['x']) -> Callable:
        """Convert symbolic expression to callable numpy function."""
        if SYMPY_AVAILABLE:
            sym_vars = symbols(' '.join(vars))
            expr = sympy.sympify(expr_str)
            return lambdify(sym_vars, expr, modules=['numpy'])
        else:
            # Return identity function as fallback
            return lambda *args: float('nan')
    
    # ─────────────────────────────────────────────────────────────────────────
    # SPECIAL FUNCTIONS
    # ─────────────────────────────────────────────────────────────────────────
    
    @staticmethod
    def bessel_j(n: int, x: float) -> float:
        """Bessel function of the first kind J_n(x)."""
        if SCIPY_AVAILABLE:
            from scipy.special import jv
            return float(jv(n, x))
        else:
            # Simple approximation for J_0 only
            if n == 0 and abs(x) < 3:
                return 1 - (x/2)**2 + (x/2)**4/4 - (x/2)**6/36
            return float('nan')
    
    @staticmethod
    def spherical_harmonics(l: int, m: int, theta: float, phi: float) -> complex:
        """Spherical harmonics Y_l^m(theta, phi)."""
        if SCIPY_AVAILABLE:
            from scipy.special import sph_harm
            return complex(sph_harm(m, l, phi, theta))
        else:
            return complex('nan')
    
    @staticmethod 
    def gamma_func(x: float) -> float:
        """Gamma function Γ(x)."""
        if SCIPY_AVAILABLE:
            from scipy.special import gamma
            return float(gamma(x))
        else:
            # Stirling approximation for large x
            if x > 0:
                return math.sqrt(2 * math.pi / x) * (x / math.e) ** x
            return float('nan')
    
    # ─────────────────────────────────────────────────────────────────────────
    # STIFF ODE SOLVERS (BDF, Radau)
    # ─────────────────────────────────────────────────────────────────────────
    
    @staticmethod
    def bdf_solve(f: Callable, t_span: Tuple[float, float], y0: np.ndarray,
                  rtol: float = 1e-6, atol: float = 1e-9, max_step: float = np.inf,
                  *args) -> Tuple[np.ndarray, np.ndarray]:
        """
        Solve stiff ODEs using Backward Differentiation Formula (BDF).
        
        UQFF Application: Stellar evolution, nuclear reaction networks,
        chemical kinetics in astrophysical plasmas.
        
        Args:
            f: Function dy/dt = f(t, y, *args)
            t_span: (t_start, t_end)
            y0: Initial state
            rtol, atol: Tolerances
            max_step: Maximum step size
            *args: Additional arguments
            
        Returns:
            t, y arrays
        """
        if SCIPY_AVAILABLE:
            from scipy.integrate import solve_ivp
            sol = solve_ivp(lambda t, y: f(t, y, *args), t_span, np.atleast_1d(y0),
                           method='BDF', rtol=rtol, atol=atol, max_step=max_step)
            return sol.t, sol.y.T
        else:
            # Fallback to implicit Euler (first-order BDF)
            return NumericalMethods.euler_implicit(f, t_span, y0, n_steps=1000, *args)
    
    @staticmethod
    def radau_solve(f: Callable, t_span: Tuple[float, float], y0: np.ndarray,
                    rtol: float = 1e-6, atol: float = 1e-9,
                    *args) -> Tuple[np.ndarray, np.ndarray]:
        """
        Solve stiff ODEs using implicit Radau IIA method (5th order).
        
        More stable than BDF for extremely stiff problems.
        """
        if SCIPY_AVAILABLE:
            from scipy.integrate import solve_ivp
            sol = solve_ivp(lambda t, y: f(t, y, *args), t_span, np.atleast_1d(y0),
                           method='Radau', rtol=rtol, atol=atol)
            return sol.t, sol.y.T
        else:
            return NumericalMethods.euler_implicit(f, t_span, y0, n_steps=1000, *args)
    
    # ─────────────────────────────────────────────────────────────────────────
    # OPTIMIZATION
    # ─────────────────────────────────────────────────────────────────────────
    
    @staticmethod
    def minimize(f: Callable, x0: np.ndarray, method: str = 'BFGS',
                 bounds: List[Tuple[float, float]] = None,
                 constraints: dict = None, **kwargs) -> dict:
        """
        General-purpose optimization (scipy.optimize.minimize wrapper).
        
        UQFF Application: Parameter fitting, energy minimization,
        orbital element optimization, UQFF constant calibration.
        
        Args:
            f: Objective function to minimize
            x0: Initial guess
            method: 'BFGS', 'L-BFGS-B', 'Nelder-Mead', 'Powell', 'SLSQP'
            bounds: List of (min, max) for each variable (for L-BFGS-B, SLSQP)
            constraints: Constraint dict (for SLSQP)
            **kwargs: Additional arguments
            
        Returns:
            dict with 'x' (solution), 'fun' (minimum value), 'success'
        """
        if SCIPY_AVAILABLE:
            from scipy.optimize import minimize as scipy_minimize
            result = scipy_minimize(f, x0, method=method, bounds=bounds,
                                   constraints=constraints, **kwargs)
            return {
                'x': result.x,
                'fun': result.fun,
                'success': result.success,
                'message': result.message,
                'nit': getattr(result, 'nit', 0)
            }
        else:
            # Fallback: Simple gradient descent
            x = np.atleast_1d(x0).copy().astype(float)
            learning_rate = kwargs.get('learning_rate', 0.01)
            maxiter = kwargs.get('maxiter', 1000)
            tol = kwargs.get('tol', 1e-8)
            
            for i in range(maxiter):
                # Numerical gradient
                grad = np.zeros_like(x)
                h = 1e-8
                fx = f(x)
                for j in range(len(x)):
                    x_h = x.copy()
                    x_h[j] += h
                    grad[j] = (f(x_h) - fx) / h
                
                x_new = x - learning_rate * grad
                
                # Apply bounds if provided
                if bounds:
                    for j, (lo, hi) in enumerate(bounds):
                        if lo is not None:
                            x_new[j] = max(lo, x_new[j])
                        if hi is not None:
                            x_new[j] = min(hi, x_new[j])
                
                if np.linalg.norm(x_new - x) < tol:
                    break
                x = x_new
            
            return {'x': x, 'fun': f(x), 'success': True, 'message': 'Gradient descent fallback', 'nit': i+1}
    
    @staticmethod
    def curve_fit(f: Callable, xdata: np.ndarray, ydata: np.ndarray,
                  p0: np.ndarray = None, bounds: Tuple = (-np.inf, np.inf),
                  **kwargs) -> Tuple[np.ndarray, np.ndarray]:
        """
        Nonlinear curve fitting (scipy.optimize.curve_fit wrapper).
        
        UQFF Application: Fitting rotation curves, luminosity functions,
        spectral energy distributions.
        
        Args:
            f: Model function f(x, *params)
            xdata: x values
            ydata: y values
            p0: Initial parameter guesses
            bounds: Parameter bounds
            
        Returns:
            (optimal_params, covariance_matrix)
        """
        if SCIPY_AVAILABLE:
            from scipy.optimize import curve_fit as scipy_curve_fit
            return scipy_curve_fit(f, xdata, ydata, p0=p0, bounds=bounds, **kwargs)
        else:
            # Very basic least squares via minimize
            if p0 is None:
                p0 = np.ones(3)  # Default guess
            
            def residual(params):
                return np.sum((ydata - f(xdata, *params))**2)
            
            result = NumericalMethods.minimize(residual, p0)
            return result['x'], np.eye(len(p0)) * 0.01  # Dummy covariance
    
    # ─────────────────────────────────────────────────────────────────────────
    # INTERPOLATION
    # ─────────────────────────────────────────────────────────────────────────
    
    @staticmethod
    def interp1d(x: np.ndarray, y: np.ndarray, kind: str = 'linear') -> Callable:
        """
        1D interpolation (scipy.interpolate.interp1d wrapper).
        
        Args:
            x: x data points (must be sorted)
            y: y data points
            kind: 'linear', 'cubic', 'quadratic', 'nearest'
            
        Returns:
            Interpolation function
        """
        if SCIPY_AVAILABLE:
            from scipy.interpolate import interp1d as scipy_interp1d
            return scipy_interp1d(x, y, kind=kind, fill_value='extrapolate')
        else:
            # Linear interpolation fallback
            def linear_interp(xi):
                xi = np.atleast_1d(xi)
                result = np.zeros_like(xi)
                for i, xv in enumerate(xi):
                    idx = np.searchsorted(x, xv)
                    if idx == 0:
                        result[i] = y[0]
                    elif idx >= len(x):
                        result[i] = y[-1]
                    else:
                        t = (xv - x[idx-1]) / (x[idx] - x[idx-1])
                        result[i] = y[idx-1] + t * (y[idx] - y[idx-1])
                return result if len(result) > 1 else result[0]
            return linear_interp
    
    @staticmethod
    def cubic_spline(x: np.ndarray, y: np.ndarray) -> Callable:
        """
        Cubic spline interpolation.
        
        UQFF Application: Smooth interpolation of rotation curves,
        spectral data, time series.
        """
        if SCIPY_AVAILABLE:
            from scipy.interpolate import CubicSpline
            return CubicSpline(x, y, extrapolate=True)
        else:
            return NumericalMethods.interp1d(x, y, kind='linear')
    
    # ─────────────────────────────────────────────────────────────────────────
    # MONTE CARLO METHODS
    # ─────────────────────────────────────────────────────────────────────────
    
    @staticmethod
    def monte_carlo_integrate(f: Callable, bounds: List[Tuple[float, float]],
                              n_samples: int = 100000, seed: int = None) -> Tuple[float, float]:
        """
        Monte Carlo integration over hyperrectangle.
        
        UQFF Application: High-dimensional phase space integrals,
        partition functions, path integrals.
        
        Args:
            f: Integrand function
            bounds: List of (min, max) for each dimension
            n_samples: Number of random samples
            seed: Random seed for reproducibility
            
        Returns:
            (integral_estimate, standard_error)
        """
        if seed is not None:
            np.random.seed(seed)
        
        ndim = len(bounds)
        volume = np.prod([b[1] - b[0] for b in bounds])
        
        # Generate random samples
        samples = np.zeros((n_samples, ndim))
        for i, (lo, hi) in enumerate(bounds):
            samples[:, i] = np.random.uniform(lo, hi, n_samples)
        
        # Evaluate function
        values = np.array([f(*s) for s in samples])
        
        # Estimate and error
        mean_val = np.mean(values)
        integral = volume * mean_val
        variance = np.var(values, ddof=1)
        std_error = volume * np.sqrt(variance / n_samples)
        
        return integral, std_error
    
    @staticmethod
    def metropolis_hastings(log_prob: Callable, x0: np.ndarray, n_samples: int = 10000,
                            proposal_std: float = 1.0, burn_in: int = 1000,
                            seed: int = None) -> np.ndarray:
        """
        Metropolis-Hastings MCMC sampler.
        
        UQFF Application: Bayesian parameter estimation, posterior sampling,
        thermodynamic ensemble generation.
        
        Args:
            log_prob: Log probability function (unnormalized)
            x0: Initial state
            n_samples: Number of samples after burn-in
            proposal_std: Standard deviation of Gaussian proposal
            burn_in: Number of burn-in samples to discard
            seed: Random seed
            
        Returns:
            samples: Array of shape (n_samples, dim)
        """
        if seed is not None:
            np.random.seed(seed)
        
        x = np.atleast_1d(x0).copy().astype(float)
        ndim = len(x)
        
        samples = []
        n_accept = 0
        
        for i in range(n_samples + burn_in):
            # Propose new state
            x_new = x + np.random.normal(0, proposal_std, ndim)
            
            # Accept/reject
            log_alpha = log_prob(x_new) - log_prob(x)
            
            if np.log(np.random.random()) < log_alpha:
                x = x_new
                n_accept += 1
            
            if i >= burn_in:
                samples.append(x.copy())
        
        return np.array(samples)
    
