    def compute_U_dp(self, params: SystemParams = None, 
                     A1: float = None, A2: float = None, 
                     f_dp: float = None, phi_dp: float = None) -> Tuple[float, str]:
        """
        Compute U_dp - Di-Pseudo-Monopole Attraction Potential
        
        U_dp = k × (A₁ × A₂) / f_dp² × cos(φ_dp)
        
        Parameters:
            params: SystemParams (uses default DPM constants if None)
            A1: Channel 1 amplitude (V) - optional override
            A2: Channel 2 amplitude (V) - optional override  
            f_dp: DPM frequency (Hz) - optional override
            phi_dp: Phase angle (rad) - optional override
            
        Returns:
            U_dp value and calculation steps
            
        PHYSICAL MEANING:
            DPM attraction occurs between ordered dipole moment phases.
            At φ_dp = 0, maximum attraction (constructive interference).
            At φ_dp = π, maximum repulsion (destructive interference).
        """
        # Use CONSTANTS defaults or overrides
        k = CONSTANTS['k_DPM']
        A1 = A1 if A1 is not None else CONSTANTS['A1_DPM']
        A2 = A2 if A2 is not None else CONSTANTS['A2_DPM']
        f_dp = f_dp if f_dp is not None else CONSTANTS['f_dp']
        phi_dp = phi_dp if phi_dp is not None else CONSTANTS['phi_dp']
        
        # U_dp = k × (A₁ × A₂) / f_dp² × cos(φ_dp)
        amplitude_product = A1 * A2
        frequency_factor = f_dp ** 2
        phase_factor = np.cos(phi_dp)
        
        U_dp = k * (amplitude_product / frequency_factor) * phase_factor
        
        steps = f"""
    U_dp (DPM Attraction Potential)
    ═══════════════════════════════════════════════════════════════
    
    EQUATION: U_dp = k × (A₁ × A₂) / f_dp² × cos(φ_dp)
    
    Step 1: Coupling constant
            k = {k:.4e} m³/kg/s² (gravitational coupling)
    
    Step 2: Amplitude product
            A₁ = {A1:.4f} V (Channel 1)
            A₂ = {A2:.4f} V (Channel 2)
            A₁ × A₂ = {amplitude_product:.4f} V²
    
    Step 3: Frequency factor
            f_dp = {f_dp:.2f} Hz
            f_dp² = {frequency_factor:.4f} Hz²
    
    Step 4: Phase factor
            φ_dp = {phi_dp:.4f} rad
            cos(φ_dp) = {phase_factor:.4f}
    
    Step 5: Final U_dp
            U_dp = {k:.4e} × ({amplitude_product:.4f} / {frequency_factor:.4f}) × {phase_factor:.4f}
            U_dp = {U_dp:.4e} (arbitrary units, scaled by system mass)
    
    INTERPRETATION:
            {'Maximum attraction (in-phase)' if abs(phase_factor - 1.0) < 0.01 else
             'Maximum repulsion (anti-phase)' if abs(phase_factor + 1.0) < 0.01 else
             f'Partial coupling (phase offset)'}"""
        
        return U_dp, steps
    
    def compute_U_r(self, t: float, A: float = None, A2: float = None,
                    f: float = None, phi: float = None) -> Tuple[float, str]:
        """
        Compute U_r - Universal Resonance (Q-wave Interaction)
        
        U_r = A × sin(2πft) + A₂ × sin(2πft + φ)
        
        Parameters:
            t: Time (s)
            A: Primary amplitude (V) - optional override
            A2: Secondary amplitude (V) - optional override
            f: Frequency (Hz) - optional override
            phi: Phase offset (rad) - optional override
            
        Returns:
            U_r value and calculation steps
            
        PHYSICAL MEANING:
            Q-wave superposition creates standing wave patterns.
            When φ = π/2: Quadrature coupling (orthogonal Q-states).
            When φ = 0: Pure constructive interference.
        """
        # Use CONSTANTS defaults or overrides
        A = A if A is not None else CONSTANTS['A_Ur']
        A2 = A2 if A2 is not None else CONSTANTS['A2_Ur']
        f = f if f is not None else CONSTANTS['f_Ur']
        phi = phi if phi is not None else CONSTANTS['phi_Ur']
        
        # U_r = A × sin(2πft) + A₂ × sin(2πft + φ)
        omega_t = 2 * np.pi * f * t
        term1 = A * np.sin(omega_t)
        term2 = A2 * np.sin(omega_t + phi)
        
        U_r = term1 + term2
        
        steps = f"""
    U_r (Universal Resonance / Q-Wave Interaction)
    ═══════════════════════════════════════════════════════════════
    
    EQUATION: U_r = A × sin(2πft) + A₂ × sin(2πft + φ)
    
    Step 1: Frequency and time
            t = {t:.6f} s
            f = {f:.2f} Hz
            2πft = {omega_t:.4f} rad
    
    Step 2: Primary Q-wave term
            A = {A:.4f} V
            A × sin(2πft) = {A:.4f} × sin({omega_t:.4f})
            Term 1 = {term1:.4f} V
    
    Step 3: Secondary Q-wave term (phase-shifted)
            A₂ = {A2:.4f} V
            φ = {phi:.4f} rad
            A₂ × sin(2πft + φ) = {A2:.4f} × sin({omega_t + phi:.4f})
            Term 2 = {term2:.4f} V
    
    Step 4: Total resonance
            U_r = {term1:.4f} + {term2:.4f}
            U_r = {U_r:.4f} V
    
    INTERPRETATION:
            Instantaneous Q-wave superposition at t = {t:.6f} s
            {'Peak constructive' if abs(U_r) > (A + A2) * 0.9 else
             'Near null (destructive)' if abs(U_r) < 0.1 else
             'Intermediate superposition'}"""
        
        return U_r, steps
    
    def compute_SC_m(self, psi_local: float, psi_integral: float) -> Tuple[float, str]:
        """
        Compute SC_m - Coherence Metric (Superconductive Material)
        
        SC_m = |ψ|² / ∫|ψ|²dV
        
        Parameters:
            psi_local: Local wave function magnitude |ψ| at point
            psi_integral: Volume integral of |ψ|² over domain
            
        Returns:
            SC_m value and calculation steps
            
        PHYSICAL MEANING:
            SC_m measures normalized coherence of superconductive field.
            SC_m → 1: Perfect point-like coherence (delta function limit).
            SC_m → 0: Distributed/decoherent state.
        """
        if psi_integral <= 0:
            raise ValueError("Integral ∫|ψ|²dV must be positive")
        
        # SC_m = |ψ|² / ∫|ψ|²dV
        psi_squared = psi_local ** 2
        SC_m = psi_squared / psi_integral
        
        # Clamp to [0, 1] for physical interpretation
        SC_m_clamped = min(max(SC_m, 0.0), 1.0)
        
        steps = f"""
    SC_m (Coherence Metric)
    ═══════════════════════════════════════════════════════════════
    
    EQUATION: SC_m = |ψ|² / ∫|ψ|²dV
    
    Step 1: Local wave function
            |ψ| = {psi_local:.6e}
            |ψ|² = {psi_squared:.6e}
    
    Step 2: Volume integral
            ∫|ψ|²dV = {psi_integral:.6e}
    
    Step 3: Coherence metric
            SC_m = {psi_squared:.6e} / {psi_integral:.6e}
            SC_m = {SC_m:.6e}
            SC_m (clamped) = {SC_m_clamped:.6f}
    
    INTERPRETATION:
            {'Perfect coherence (delta-like)' if SC_m_clamped > 0.99 else
             'High coherence (stable orbits)' if SC_m_clamped > 0.9 else
             'Moderate coherence (transitional)' if SC_m_clamped > 0.5 else
             'Low coherence (diffuse)' if SC_m_clamped > 0.1 else
             'Minimal coherence (decoherent)'}
            
    REFERENCE VALUES:
            SC_m_ideal = {CONSTANTS['SC_m_ideal']:.2f}
            SC_m_orbital = {CONSTANTS['SC_m_orbital']:.2f}
            SC_m_diffuse = {CONSTANTS['SC_m_diffuse']:.2f}"""
        
        return SC_m_clamped, steps
    
    def compute_P_stable(self, wavelength: float, mu: float = None, 
                         sigma: float = None) -> Tuple[float, str]:
        """
        Compute P_stable - Orbital Stability Probability
        
        P_stable = exp(-((log λ - μ)² / (2σ²)))
        
        Parameters:
            wavelength: Orbital resonance wavelength λ (∝ semi-major axis)
            mu: Mean of log-wavelengths (default from CONSTANTS)
            sigma: Std dev of log-wavelengths (default from CONSTANTS)
            
        Returns:
            P_stable value and calculation steps
            
        PHYSICAL MEANING:
            Log-normal distribution for orbital stability.
            P_stable ≈ 1 at resonant orbits (e.g., MMR locations).
            P_stable → 0 for unstable regions.
        """
        mu = mu if mu is not None else CONSTANTS['P_stable_mu']
        sigma = sigma if sigma is not None else CONSTANTS['P_stable_sigma']
        
        if wavelength <= 0:
            raise ValueError("Wavelength must be positive")
        if sigma <= 0:
            raise ValueError("Sigma must be positive")
        
        # P_stable = exp(-((log λ - μ)² / (2σ²)))
        log_lambda = np.log(wavelength)
        deviation = log_lambda - mu
        variance = 2 * sigma ** 2
        exponent = -(deviation ** 2) / variance
        
        P_stable = np.exp(exponent)
        
        steps = f"""
    P_stable (Orbital Stability Probability)
    ═══════════════════════════════════════════════════════════════
    
    EQUATION: P_stable = exp(-((log λ - μ)² / (2σ²)))
    
    Step 1: Orbital wavelength
            λ = {wavelength:.6e}
            log(λ) = {log_lambda:.6f}
    
    Step 2: Distribution parameters
            μ = {mu:.4f} (log-mean of stable orbits)
            σ = {sigma:.4f} (log-std dev)
    
    Step 3: Deviation from mean
            log(λ) - μ = {deviation:.6f}
            (log(λ) - μ)² = {deviation**2:.6f}
    
    Step 4: Variance factor
            2σ² = {variance:.6f}
    
    Step 5: Probability calculation
            exponent = -{deviation**2:.6f} / {variance:.6f} = {exponent:.6f}
            P_stable = exp({exponent:.6f})
            P_stable = {P_stable:.6f}
    
    INTERPRETATION:
            {'Highly stable orbit (resonant)' if P_stable > 0.9 else
             'Moderately stable' if P_stable > 0.5 else
             'Marginally stable' if P_stable > 0.1 else
             'Unstable region'}"""
        
        return P_stable, steps
    
    def compute_Q_wave_dynamic(self, delta_V: float, exponent: int = None) -> Tuple[float, str]:
        """
        Compute Q-wave (dynamic)⁴ = dynamic potential difference
        
        Q-wave dynamics: (ΔV)^n where n = 4 (fractal equilibrium)
        
        Parameters:
            delta_V: Potential difference ΔV (V)
            exponent: Power exponent (default 4 from CONSTANTS)
            
        Returns:
            Q_dynamic value and calculation steps
            
        PHYSICAL MEANING:
            The 4th power represents fractal equilibrium: DPM = [(-UA'):(+SCm)]
            26 frequency Shell for ACP (Atomic-Creation-Point)
            The quartic emerges from 26/6.5 = 4 quadrants of EM shell
        """
        n = exponent if exponent is not None else CONSTANTS['Q_dynamic_exponent']
        
        Q_dynamic = abs(delta_V) ** n
        
        # Sign correction: preserve sign for odd powers
        if n % 2 == 1 and delta_V < 0:
            Q_dynamic = -Q_dynamic
        
        steps = f"""
    Q-wave (dynamic)^n
    ═══════════════════════════════════════════════════════════════
    
    EQUATION: Q-wave = (ΔV)^n = (dynamic potential difference)
    
    Step 1: Potential difference
            ΔV = {delta_V:.6f} V
    
    Step 2: Exponent (fractal equilibrium)
            n = {n} (from 26 shell / 6.5 quadrants)
    
    Step 3: Q-wave calculation
            |ΔV|^{n} = |{delta_V:.6f}|^{n}
            Q_dynamic = {Q_dynamic:.6e}
    
    FRACTAL INTERPRETATION:
            DPM = [(-UA'):(+SCm)] fractal dynamic equilibrium
            26 frequency Shell for ACP (Atomic-Creation-Point)
            
    THz HOLE CONTEXT:
            f_min = {CONSTANTS['f_THz_hole_min']:.2e} Hz
            f_max = {CONSTANTS['f_THz_hole_max']:.2e} Hz
            Signal reversal mechanism at 1.2-1.3 THz"""
        
        return Q_dynamic, steps
    
    def compute_U_grav(self, params: SystemParams, t: float,
                       psi_local: float = 1.0, psi_integral: float = 1.0,
                       wavelength: float = 1.0) -> Tuple[float, Dict[str, float], str]:
        """
        Compute U_grav - Master Universal Gravity Equation
        
        U_grav = U_dp + U_r + SC_m × k_SM × P_stable
        
        Parameters:
            params: SystemParams for the system
            t: Time (s) for resonance calculation
            psi_local: Local |ψ| for coherence (default 1.0)
            psi_integral: ∫|ψ|²dV for coherence (default 1.0)
            wavelength: Orbital wavelength for stability (default 1.0)
            
        Returns:
            U_grav total, component dict, and calculation steps
            
        PHYSICAL MEANING:
            Unified framework combining:
            - DPM attraction (classical-like)
            - Q-wave resonance (quantum oscillation)
            - Coherence × Standard Model coupling × Orbital stability
        """
        k_SM = CONSTANTS['k_SM']
        
        # Compute components
        U_dp, _ = self.compute_U_dp(params)
        U_r, _ = self.compute_U_r(t)
        SC_m, _ = self.compute_SC_m(psi_local, psi_integral)
        P_stable, _ = self.compute_P_stable(wavelength)
        
        # Coherence contribution
        coherence_term = SC_m * k_SM * P_stable
        
        # Master equation: U_grav = U_dp + U_r + SC_m × k_SM × P_stable
        U_grav = U_dp + U_r + coherence_term
        
        components = {
            'U_dp': U_dp,
            'U_r': U_r,
            'SC_m': SC_m,
            'k_SM': k_SM,
            'P_stable': P_stable,
            'coherence_term': coherence_term,
            'U_grav': U_grav,
        }
        
        steps = f"""
    U_grav (Master Universal Gravity Equation)
    ═══════════════════════════════════════════════════════════════════════════════
    
    MASTER EQUATION: U_grav = U_dp + U_r + SC_m × k_SM × P_stable
    
    ───────────────────────────────────────────────────────────────────────────────
    COMPONENT 1: U_dp (DPM Attraction)
    ───────────────────────────────────────────────────────────────────────────────
        U_dp = k × (A₁ × A₂) / f_dp² × cos(φ_dp)
        U_dp = {U_dp:.6e}
    
    ───────────────────────────────────────────────────────────────────────────────
    COMPONENT 2: U_r (Universal Resonance)
    ───────────────────────────────────────────────────────────────────────────────
        U_r = A × sin(2πft) + A₂ × sin(2πft + φ)
        At t = {t:.6f} s:
        U_r = {U_r:.6f} V
    
    ───────────────────────────────────────────────────────────────────────────────
    COMPONENT 3: Coherence-Stability Term
    ───────────────────────────────────────────────────────────────────────────────
        SC_m = |ψ|² / ∫|ψ|²dV = {SC_m:.6f}
        k_SM = {k_SM:.6e} (Standard Model coupling)
        P_stable = {P_stable:.6f}
        
        SC_m × k_SM × P_stable = {coherence_term:.6e}
    
    ───────────────────────────────────────────────────────────────────────────────
    TOTAL: U_grav
    ───────────────────────────────────────────────────────────────────────────────
        U_grav = {U_dp:.6e} + {U_r:.6f} + {coherence_term:.6e}
        U_grav = {U_grav:.6f}
    
    INTERPRETATION:
        The dominant term is {'U_dp (DPM attraction)' if abs(U_dp) > abs(U_r) and abs(U_dp) > abs(coherence_term) else
                             'U_r (resonance)' if abs(U_r) > abs(coherence_term) else
                             'Coherence-stability term'}
        
    BALANCE ANALYSIS:
        |U_dp| / |U_grav| = {abs(U_dp)/abs(U_grav)*100 if U_grav != 0 else 0:.2f}%
        |U_r| / |U_grav| = {abs(U_r)/abs(U_grav)*100 if U_grav != 0 else 0:.2f}%
        Coherence / |U_grav| = {abs(coherence_term)/abs(U_grav)*100 if U_grav != 0 else 0:.2f}%"""
        
        return U_grav, components, steps
    
    def compute_SCm_evolution(self, epoch: int) -> Tuple[str, float, str]:
        """
        Compute SCm evolution state based on cosmic epoch
        
        SCm → SCm' → SCm'' → SCm''' → SCm''''
        
        Parameters:
            epoch: Cosmic epoch (1-5)
            
        Returns:
            SCm state name, coherence factor, and description
            
        PHYSICAL MEANING:
            Each prime (') denotes increasing complexity/structure.
            Higher epochs support more complex cosmic objects.
        """
        SCm_states = CONSTANTS.get('SCm_state_names', ['SCm', "SCm'", "SCm''", "SCm'''", "SCm''''"])
        
        if epoch < 1:
            epoch = 1
        if epoch > 5:
            epoch = 5
        
        state_name = SCm_states[epoch - 1]
        
        # Coherence factor increases with epoch (more structured matter)
        coherence_factors = {
            1: 0.70,   # Nuclei/Elements - moderate coherence
            2: 0.85,   # Stars/Planets - higher coherence
            3: 0.92,   # Galaxies - near peak
            4: 0.97,   # Magnetars/SMBH - extreme coherence
            5: 0.99,   # Globular clusters - highest coherence
        }
        coherence = coherence_factors.get(epoch, 0.8)
        
        epoch_objects = self.epochs.get(epoch, {}).get('objects', ['Unknown'])
        
        steps = f"""
    SCm Evolution at Epoch {epoch}
    ═══════════════════════════════════════════════════════════════
    
    EVOLUTION CHAIN: SCm → SCm' → SCm'' → SCm''' → SCm''''
    
    Current State: {state_name}
    Epoch Range: t ∈ [{epoch}.0, {epoch}.9]
    Coherence Factor: {coherence:.2f}
    
    Associated Objects:
        {', '.join(epoch_objects)}
    
    PHYSICAL INTERPRETATION:
        SCm represents superconductive material organization.
        Higher primes indicate more complex matter structuring.
        
    COHERENCE PROGRESSION:
        SCm  (Epoch 1): 0.70 - Nuclei formation
        SCm' (Epoch 2): 0.85 - Stellar assembly
        SCm''(Epoch 3): 0.92 - Galactic binding
        SCm'''(Epoch 4): 0.97 - Extreme density objects
        SCm''''(Epoch 5): 0.99 - Large-scale structure"""
        
        return state_name, coherence, steps
    
    def validate_master_gravity_physics(self, params: SystemParams = None) -> Tuple[bool, Dict[str, Any], str]:
        """
        Validate Master Universal Gravity Equation physics
        
        Tests:
            1. U_dp positive for in-phase coupling
            2. U_r bounded by amplitude sum
            3. SC_m in [0, 1]
            4. P_stable in [0, 1] with peak at λ = exp(μ)
            5. Q-wave quartic positive definite
            6. U_grav components sum correctly
            
        Returns:
            all_pass, results dict, and detailed steps
        """
        # Use default params if none provided
        if params is None:
            params = SystemParams(
                name="Solar System Reference",
                M=1.989e30,           # Solar mass
                r=1.496e11,           # 1 AU
                rho_fluid=1e-20,      # Interplanetary density
                T=5778,               # Solar surface temp
                V_sys=4.19e12 ** 3,   # 1 AU sphere
            )
        
        results = {}
        all_pass = True
        
        # Test 1: U_dp positive for in-phase (phi_dp = 0)
        U_dp, _ = self.compute_U_dp(params, phi_dp=0.0)
        results['U_dp_positive'] = U_dp > 0
        if not results['U_dp_positive']:
            all_pass = False
        
        # Test 2: U_dp negative for anti-phase (phi_dp = π)
        U_dp_anti, _ = self.compute_U_dp(params, phi_dp=np.pi)
        results['U_dp_anti_negative'] = U_dp_anti < 0
        if not results['U_dp_anti_negative']:
            all_pass = False
        
        # Test 3: U_r bounded by |A + A₂|
        A = CONSTANTS['A_Ur']
        A2 = CONSTANTS['A2_Ur']
        max_amplitude = A + A2
        
        # Sample U_r at multiple times
        U_r_samples = [self.compute_U_r(t)[0] for t in np.linspace(0, 1, 100)]
        max_U_r = max(abs(u) for u in U_r_samples)
        results['U_r_bounded'] = max_U_r <= max_amplitude * 1.01  # 1% tolerance
        if not results['U_r_bounded']:
            all_pass = False
        
        # Test 4: SC_m in [0, 1]
        SC_m_test, _ = self.compute_SC_m(0.5, 1.0)  # 0.5² / 1.0 = 0.25
        results['SC_m_in_range'] = 0 <= SC_m_test <= 1
        if not results['SC_m_in_range']:
            all_pass = False
        
        # Test 5: P_stable peaks at λ = exp(μ) = exp(0) = 1
        P_stable_peak, _ = self.compute_P_stable(1.0)  # λ = 1, log(1) = 0 = μ
        results['P_stable_peak_at_unity'] = P_stable_peak > 0.99
        if not results['P_stable_peak_at_unity']:
            all_pass = False
        
        # Test 6: P_stable in [0, 1]
        P_stable_low, _ = self.compute_P_stable(0.01)  # Far from peak
        P_stable_high, _ = self.compute_P_stable(100.0)  # Far from peak
        results['P_stable_in_range'] = 0 <= P_stable_low <= 1 and 0 <= P_stable_high <= 1
        if not results['P_stable_in_range']:
            all_pass = False
        
        # Test 7: Q-wave quartic positive definite
        Q_pos, _ = self.compute_Q_wave_dynamic(1.5)
        Q_neg, _ = self.compute_Q_wave_dynamic(-1.5)
        results['Q_positive_definite'] = Q_pos > 0 and Q_neg > 0  # |ΔV|⁴ > 0
        if not results['Q_positive_definite']:
            all_pass = False
        
        # Test 8: U_grav components sum correctly
        U_grav, components, _ = self.compute_U_grav(params, t=0.001)
        expected = components['U_dp'] + components['U_r'] + components['coherence_term']
        results['U_grav_sum_correct'] = abs(U_grav - expected) < 1e-10
        if not results['U_grav_sum_correct']:
            all_pass = False
        
        # Generate report
        steps = f"""
    MASTER UNIVERSAL GRAVITY EQUATION VALIDATION
    ═══════════════════════════════════════════════════════════════════════════════
    
    TEST RESULTS:
    ─────────────────────────────────────────────────────────────────────────────
    1. U_dp positive (in-phase):      {'✓ PASS' if results['U_dp_positive'] else '✗ FAIL'}
       U_dp(φ=0) = {U_dp:.6e} > 0
       
    2. U_dp negative (anti-phase):    {'✓ PASS' if results['U_dp_anti_negative'] else '✗ FAIL'}
       U_dp(φ=π) = {U_dp_anti:.6e} < 0
       
    3. U_r bounded by amplitudes:     {'✓ PASS' if results['U_r_bounded'] else '✗ FAIL'}
       max|U_r| = {max_U_r:.4f} ≤ {max_amplitude:.4f}
       
    4. SC_m in [0, 1]:               {'✓ PASS' if results['SC_m_in_range'] else '✗ FAIL'}
       SC_m(0.5, 1.0) = {SC_m_test:.4f}
       
    5. P_stable peaks at λ=1:        {'✓ PASS' if results['P_stable_peak_at_unity'] else '✗ FAIL'}
       P_stable(1.0) = {P_stable_peak:.6f} > 0.99
       
    6. P_stable in [0, 1]:           {'✓ PASS' if results['P_stable_in_range'] else '✗ FAIL'}
       P_stable(0.01) = {P_stable_low:.6f}
       P_stable(100) = {P_stable_high:.6f}
       
    7. Q-wave positive definite:      {'✓ PASS' if results['Q_positive_definite'] else '✗ FAIL'}
       Q(+1.5) = {Q_pos:.6f} > 0
       Q(-1.5) = {Q_neg:.6f} > 0
       
    8. U_grav sum correct:           {'✓ PASS' if results['U_grav_sum_correct'] else '✗ FAIL'}
       |U_grav - Σ components| = {abs(U_grav - expected):.2e}
    
    ─────────────────────────────────────────────────────────────────────────────
    SUMMARY: {sum(results.values())}/{len(results)} tests passed
    ─────────────────────────────────────────────────────────────────────────────
    {'ALL TESTS PASSED ✓' if all_pass else 'SOME TESTS FAILED ✗'}
    """
        
        return all_pass, results, steps
    
