        r_s, _ = self.compute_Schwarzschild_radius(M_BH)
        T_H, _ = self.compute_Hawking_temperature(M_BH)
        tau_BH, _ = self.compute_BH_lifetime(M_BH)
        
        M_ratio = M_BH / M_initial if M_initial > 0 else 1.0
        
        # Determine phase
        if M_ratio <= self.phase_thresholds['final']:
            phase = 'PHASE 5: Final Evaporation'
            description = 'Quantum corrections dominate, final burst imminent'
        elif M_ratio <= self.phase_thresholds['evaporation']:
            phase = 'PHASE 4: Evaporation'
