# ═══════════════════════════════════════════════════════════════════════════════
# UNIFIED MODEL: SOLAR DOMAIN (Hill Sphere + Oort Cloud Unification)
# ═══════════════════════════════════════════════════════════════════════════════

class SolarDomainModel(SelfSimulatingExpandingMixin):
    """
    Solar Domain Model - Unified Hill Sphere + Oort Cloud Boundaries
    
    INTEGRATION: Combines HillSphereModel (230k AU theoretical) with 
    OortCloudBoundaryModel (100k AU practical) into nested boundaries.
    
    NESTED BOUNDARY STRUCTURE:
    ─────────────────────────────────────────────────────────────────────────────
    
    Zone 1: PLANETARY ZONE (0 - 50 AU)
        - Classical Keplerian orbits
        - Dominated by solar gravity
        - Contains all major planets + Kuiper Belt
    
    Zone 2: SCATTERED ZONE (50 - 2,000 AU)
        - Extreme TNOs (Sedna, The Goblin)
        - Chaotic orbits, possible planet interactions
        
    Zone 3: INNER OORT CLOUD (2,000 - 20,000 AU)
        - Spherical cloud of comets
        - Weak but stable solar binding
        
    Zone 4: OUTER OORT CLOUD (20,000 - 100,000 AU)
        - Practical limit of solar control
        - Long-period comet reservoir
        
    Zone 5: EXTENDED HILL SPHERE (100,000 - 230,000 AU)
        - Theoretical gravitational dominance
        - Subject to galactic perturbations
        - Marginally bound / transient objects
    
    BOUNDARY PHYSICS:
    ─────────────────────────────────────────────────────────────────────────────
    
    Theoretical: r_H = a × (M_sun / 3M_gal)^(1/3) ≈ 230,000 AU
    Practical:   r_Oort ≈ 100,000 AU (galactic tides strip outer objects)
    """
    
    def __init__(self):
        """Initialize Solar Domain Model."""
        # Reference base models
        self.hill_model = HILL_SPHERE_MODEL
        self.oort_model = OORT_CLOUD_MODEL
        
        # Physical constants
        self.AU = 1.496e11
        self.ly = 9.461e15
        
        # Zone boundaries (AU)
        self.zones = {
            'planetary': {'inner': 0, 'outer': 50, 'color': 'blue'},
            'scattered': {'inner': 50, 'outer': 2000, 'color': 'cyan'},
            'inner_oort': {'inner': 2000, 'outer': 20000, 'color': 'green'},
            'outer_oort': {'inner': 20000, 'outer': 100000, 'color': 'yellow'},
            'extended_hill': {'inner': 100000, 'outer': 230000, 'color': 'red'}
        }
        
        # Key objects
        self.landmark_objects = {
            'Neptune': 30,
            'Pluto_aphelion': 49,
            'Eris_aphelion': 96,
            'Sedna_aphelion': 937,
            'The_Goblin_aphelion': 2300,
            'Inner_Oort_Edge': 2000,
            'Outer_Oort_Edge': 100000,
            'Hill_Sphere': 230000
        }
        
    def classify_distance(self, d_AU: float) -> Tuple[str, dict, str]:
        """
        Classify a distance into the appropriate solar domain zone.
        
        Args:
            d_AU: Distance from Sun (AU)
        
        Returns:
            zone_name: Name of the zone
            zone_info: Zone properties
            steps: Description
        """
        for zone_name, bounds in self.zones.items():
            if bounds['inner'] <= d_AU < bounds['outer']:
                zone_info = bounds.copy()
                zone_info['name'] = zone_name
                break
        else:
            zone_info = {'name': 'interstellar', 'inner': 230000, 'outer': float('inf')}
            zone_name = 'interstellar'
        
        d_ly = d_AU * self.AU / self.ly
        
        steps = f"""
    SOLAR DOMAIN CLASSIFICATION
    ══════════════════════════════════════════════════════════════════
    
    Distance: {d_AU:,.0f} AU = {d_ly:.4f} ly
    
    ZONE: {zone_name.upper().replace('_', ' ')}
    
    ZONE STRUCTURE (unified Hill + Oort):
    ──────────────────────────────────────────────────────────────────
    {'→ ' if zone_name == 'planetary' else '  '}Planetary:      0 - 50 AU
    {'→ ' if zone_name == 'scattered' else '  '}Scattered:      50 - 2,000 AU
    {'→ ' if zone_name == 'inner_oort' else '  '}Inner Oort:     2,000 - 20,000 AU
    {'→ ' if zone_name == 'outer_oort' else '  '}Outer Oort:     20,000 - 100,000 AU (practical limit)
    {'→ ' if zone_name == 'extended_hill' else '  '}Extended Hill:  100,000 - 230,000 AU (theoretical)
    ──────────────────────────────────────────────────────────────────
    
    BINDING STATUS: {'Strong solar binding' if zone_name in ['planetary', 'scattered'] else 'Weak solar binding' if zone_name in ['inner_oort', 'outer_oort'] else 'Marginal binding / transient' if zone_name == 'extended_hill' else 'Unbound / Interstellar'}
    ══════════════════════════════════════════════════════════════════"""
        
        return zone_name, zone_info, steps
    
    def compute_binding_energy(self, d_AU: float, 
                                 M_object: float = 1e12) -> Tuple[float, str]:
        """
        Compute gravitational binding energy at distance.
        
        E_bind = -G × M_sun × M_object / r
        
        Args:
            d_AU: Distance from Sun (AU)
            M_object: Object mass (kg, default ~comet)
        
        Returns:
            E_bind: Binding energy (J, negative = bound)
            steps: Derivation string
        """
        G = CONSTANTS.get('G', 6.674e-11)
        M_sun = CONSTANTS.get('M_Sun', 1.989e30)
        
        r = d_AU * self.AU
        E_bind = -G * M_sun * M_object / r
        
        # Escape velocity
        v_esc = np.sqrt(2 * G * M_sun / r)
        
        steps = f"""
    SOLAR BINDING ENERGY
    ══════════════════════════════════════════════════════════════════
    
    E_bind = -G × M_sun × M_object / r
    
    PARAMETERS:
        d = {d_AU:,.0f} AU = {r:.4e} m
        M_sun = {M_sun:.4e} kg
        M_object = {M_object:.4e} kg
    
    CALCULATION:
        E_bind = -{G:.4e} × {M_sun:.4e} × {M_object:.4e} / {r:.4e}
               = {E_bind:.4e} J
        
        v_escape = √(2GM/r) = {v_esc:.2e} m/s = {v_esc/1000:.4f} km/s
    
    ZONE COMPARISON:
        Neptune (30 AU): v_esc ≈ 7.7 km/s
        Outer Oort (100,000 AU): v_esc ≈ 0.13 km/s
        Hill Sphere (230,000 AU): v_esc ≈ 0.09 km/s
    ══════════════════════════════════════════════════════════════════"""
        
        return E_bind, steps
    
    def compute_zone_volumes(self) -> Tuple[dict, str]:
        """
        Compute volumes of each solar domain zone.
        
        Returns:
            volumes: Dictionary of zone volumes (AU³)
            steps: Description
        """
        volumes = {}
        
        for name, bounds in self.zones.items():
            r_inner = bounds['inner'] * self.AU
            r_outer = bounds['outer'] * self.AU
            V = (4/3) * np.pi * (r_outer**3 - r_inner**3)
            V_AU3 = V / (self.AU**3)
            volumes[name] = V_AU3
        
        total_V = sum(volumes.values())
        
        steps = """
    SOLAR DOMAIN ZONE VOLUMES
    ══════════════════════════════════════════════════════════════════
    
    V = (4/3)π × (r_outer³ - r_inner³)
    
    ZONE VOLUMES:
"""
        for name, V in volumes.items():
            pct = V / total_V * 100
            steps += f"        {name.replace('_', ' ').title()}: {V:.4e} AU³ ({pct:.2f}%)\n"
        
        steps += f"""
    TOTAL (to Hill Sphere): {total_V:.4e} AU³
    
    NOTE: Extended Hill zone contains 99%+ of domain volume
    but has marginal binding and transient population
    ══════════════════════════════════════════════════════════════════"""
        
        return volumes, steps
    
    def validate_model(self) -> Tuple[bool, list, str]:
        """Validate Solar Domain Model."""
        tests = []
        
        # Test 1: 5 zones defined
        tests.append({
            'name': '5 zones defined',
            'n_zones': len(self.zones),
            'passed': len(self.zones) == 5
        })
        
        # Test 2: Zones are contiguous
        zones_sorted = sorted(self.zones.values(), key=lambda x: x['inner'])
        contiguous = all(zones_sorted[i]['outer'] == zones_sorted[i+1]['inner'] 
                         for i in range(len(zones_sorted)-1))
        tests.append({
            'name': 'Zones are contiguous',
            'passed': contiguous
        })
        
        # Test 3: Neptune in planetary zone
        zone, _, _ = self.classify_distance(30)
        tests.append({
            'name': 'Neptune (30 AU) in planetary zone',
            'zone': zone,
            'passed': zone == 'planetary'
        })
        
        # Test 4: Binding energy negative (bound)
        E, _ = self.compute_binding_energy(100)
        tests.append({
            'name': 'Binding energy negative (bound)',
            'E': E,
            'passed': E < 0
        })
        
        all_passed = all(t['passed'] for t in tests)
        
        summary = f"""SOLAR DOMAIN MODEL VALIDATION
════════════════════════════════════════════════════════════════════════════════
TEST RESULTS:
────────────────────────────────────────────────────────────────────────────────
1. 5 zones defined:                {'✓ PASS' if tests[0]['passed'] else '✗ FAIL'}
   {tests[0]['n_zones']} zones

2. Zones contiguous:               {'✓ PASS' if tests[1]['passed'] else '✗ FAIL'}

3. Neptune in planetary zone:      {'✓ PASS' if tests[2]['passed'] else '✗ FAIL'}
   Classified as: {tests[2]['zone']}

4. Binding energy < 0:             {'✓ PASS' if tests[3]['passed'] else '✗ FAIL'}
   E = {tests[3]['E']:.4e} J

────────────────────────────────────────────────────────────────────────────────
SUMMARY: {sum(t['passed'] for t in tests)}/{len(tests)} tests passed
────────────────────────────────────────────────────────────────────────────────
{'ALL TESTS PASSED ✓' if all_passed else 'SOME TESTS FAILED ✗'}
════════════════════════════════════════════════════════════════════════════════
"""
        return all_passed, tests, summary

    @staticmethod
    def run_tests() -> dict:
        """Test SolarDomainModel functionality."""
        tests = []
        try:
            model = SolarDomainModel()
            tests.append({'name': 'Instantiation', 'passed': model is not None})
        except Exception as e:
            tests.append({'name': 'Instantiation', 'passed': False, 'error': str(e)})
        try:
            model = SolarDomainModel()
            has_method = hasattr(model, 'compute') or hasattr(model, 'calculate') or hasattr(model, 'get_equation_text')
            tests.append({'name': 'Has compute method', 'passed': has_method})
        except Exception as e:
            tests.append({'name': 'Has compute method', 'passed': False, 'error': str(e)})
        all_passed = all(t['passed'] for t in tests)
        return {'class': 'SolarDomainModel', 'tests': tests, 'passed': sum(1 for t in tests if t['passed']), 'total': len(tests), 'all_passed': all_passed}

    # === 8 UQFF MASTER EQUATIONS (Auto-added) ===
    
    def compute_UQFF_base(self, r=None, t=0):
        """UQFF Base: F_U = Ug1 + Ug2 + Ug3 + Ug4 - Ub + Ui"""
        import numpy as np
        G = 6.674e-11
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        Ug = G * M / r**2
        return {'Ug': Ug, 'F_U': Ug, 'equation': f"F_U = G*M/r^2 = {Ug:.3e} m/s^2"}
    
    def compute_compressed_equation(self, r=None):
        """Compressed MUGE gravity equation"""
        import numpy as np
        G, H_0 = 6.674e-11, 2.268e-18
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        g_N = G * M / r**2
        g_H = H_0**2 * r
        g = g_N - g_H
        return {'g_compressed': g, 'g_N': g_N, 'g_Hubble': g_H}
    
    def compute_resonance_equation(self, r=None, t=0):
        """Resonance MUGE with frequency modes"""
        import numpy as np
        G, H_0, c = 6.674e-11, 2.268e-18, 2.998e8
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        aDPM = G * M / r**2
        aExpFreq = H_0 * c * np.sin(H_0 * t)
        return {'g_resonance': aDPM + aExpFreq, 'aDPM': aDPM, 'aExpFreq': aExpFreq}
    
    def compute_superconductive_equation(self, T=None, T_c=None):
        """Superconductive coefficient H_SCm"""
        T = T if T else getattr(self, 'T', 4.2)
        T_c = T_c if T_c else getattr(self, 'T_c', 9.2)
        H_SCm = max(0, 1 - (T / T_c)**4) if T < T_c else 0
        return {'H_SCm': H_SCm, 'T': T, 'T_c': T_c}
    
    def compute_buoyant_equation(self, r=None, V=None):
        """Buoyancy component Ub"""
        import numpy as np
        G, rho_vac = 6.674e-11, 7.09e-36
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        if V is None: V = (4/3) * np.pi * r**3
        g = G * M / r**2
        Ub = (rho_vac * V * g) / M
        return {'Ub': Ub, 'g': g, 'V': V}
    
    def compute_master_buoyant_equation(self, r=None, v=0):
        """Master Buoyant: F_U_Bi_i = M * (Ug_i - Ub_i + Ui_i)"""
        import numpy as np
        G, rho_vac, k_eta, c = 6.674e-11, 7.09e-36, 1e-113, 2.998e8
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        V = (4/3) * np.pi * r**3
        Ug = G * M / r**2
        Ub = (rho_vac * V * Ug) / M
        Ui = -k_eta * rho_vac * V * (v / c)**2
        a_net = Ug - Ub + Ui
        return {'F_U_Bi_i': M * a_net, 'Ug': Ug, 'Ub': Ub, 'Ui': Ui, 'a_net': a_net}
    
    def compute_triadic_equation(self, r=None):
        """Triadic gravity: g_matter + g_field + g_vacuum"""
        import numpy as np
        G = 6.674e-11
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        g_matter = G * M / r**2
        g_field, g_vacuum = 1e-15, 1e-20
        return {'g_triadic': g_matter + g_field + g_vacuum, 'g_matter': g_matter}
    
    def compute_quadratic_equation(self, r=None):
        """Quadratic polynomial fit: g = a*r^2 + b*r + c"""
        import numpy as np
        G = 6.674e-11
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        g_base = G * M / r**2
        a, b, c = -1e-30, 1e-20, g_base
        return {'g_quad': a * r**2 + b * r + c, 'a': a, 'b': b, 'c': c}

    def long_form_solution(self, r=None, t=0):
        """
        Long-form solution with complete equation display.
        Returns detailed step-by-step calculation for all UQFF equations.
        """
        import numpy as np
        G = 6.674e-11
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None:
            r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        
        # Collect all equation results
        results = {}
        steps = []
        
        # 1. UQFF Base
        uqff = self.compute_UQFF_base(r, t)
        results['UQFF_base'] = uqff
        steps.append(f"UQFF Base: F_U = G*M/r^2 = {uqff['Ug']:.6e} m/s^2")
        
        # 2. Compressed equation
        comp = self.compute_compressed_equation(r)
        results['compressed'] = comp
        steps.append(f"Compressed: g = g_N - g_H = {comp['g_compressed']:.6e} m/s^2")
        
        # 3. Resonance equation
        res = self.compute_resonance_equation(r, t)
        results['resonance'] = res
        steps.append(f"Resonance: g_res = aDPM + aExpFreq = {res['g_resonance']:.6e} m/s^2")
        
        # 4. Superconductive
        sc = self.compute_superconductive_equation()
        results['superconductive'] = sc
        steps.append(f"Superconductive: H_SCm = {sc['H_SCm']:.6f}")
        
        # 5. Buoyant equation
        buoy = self.compute_buoyant_equation(r)
        results['buoyant'] = buoy
        steps.append(f"Buoyancy: Ub = {buoy['Ub']:.6e} m/s^2")
        
        # 6. Master buoyant
        master = self.compute_master_buoyant_equation(r)
        results['master_buoyant'] = master
        steps.append(f"Master Buoyant: F_U_Bi_i = {master['F_U_Bi_i']:.6e} N")
        
        # 7. Triadic
        tri = self.compute_triadic_equation(r)
        results['triadic'] = tri
        steps.append(f"Triadic: g_triadic = {tri['g_triadic']:.6e} m/s^2")
        
        # 8. Quadratic
        quad = self.compute_quadratic_equation(r)
        results['quadratic'] = quad
        steps.append(f"Quadratic: g_quad = {quad['g_quad']:.6e} m/s^2")
        
        return {
            'model': self.__class__.__name__,
            'parameters': {'M': M, 'r': r, 't': t},
            'results': results,
            'long_form': '\n'.join(steps)
        }

    def compute_master_gravity(self, r=None, t=0, include_all=True):
        """
        Master Gravity: Complete UQFF gravity computation.
        
        g_master = g_N * (1 - Ub/g_N + Ui/g_N) * H_SCm * fTRZ
        
        Combines: Newtonian, buoyancy, inertia, superconductivity, triadic zone
        """
        import numpy as np
        G = 6.674e-11
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None:
            r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        
        # Base Newtonian gravity
        g_N = G * M / r**2
        
        # Get buoyancy correction
        buoy = self.compute_buoyant_equation(r)
        Ub = buoy['Ub']
        
        # Get superconductive coefficient
        sc = self.compute_superconductive_equation()
        H_SCm = sc['H_SCm']
        
        # Get triadic factor (default: in resonance zone)
        fTRZ = 1.0
        
        # Compute master gravity
        if g_N != 0:
            correction = 1 - Ub / g_N
        else:
            correction = 1.0
        
        g_master = g_N * correction * max(0.01, H_SCm) * fTRZ
        
        # Collect additional terms if requested
        if include_all:
            comp = self.compute_compressed_equation(r)
            res = self.compute_resonance_equation(r, t)
            tri = self.compute_triadic_equation(r)
            return {
                'g_master': g_master,
                'g_N': g_N,
                'Ub': Ub,
                'H_SCm': H_SCm,
                'fTRZ': fTRZ,
                'correction': correction,
                'g_compressed': comp['g_compressed'],
                'g_resonance': res['g_resonance'],
                'g_triadic': tri['g_triadic'],
                'equation': f"g_master = g_N * (1 - Ub/g_N) * H_SCm * fTRZ = {g_master:.6e} m/s^2"
            }
        
        return {'g_master': g_master, 'g_N': g_N}





