    def compute_resonance_parameter(self, r_kpc: float = None) -> Tuple[float, float, str]:
        """
        Compute corotation resonance parameter.
        
        ξ = (r - r_co) / r_co
        S = 1 / (1 + |ξ|²)
        
        Args:
            r_kpc: Radius (kpc), default Sun's position
        
        Returns:
            xi: Resonance parameter (dimensionless)
            S: Stability factor (0-1)
            steps: Derivation string
        """
        r_kpc = r_kpc if r_kpc is not None else self.r_sun_kpc
        
        xi = (r_kpc - self.r_co) / self.r_co
        S = 1 / (1 + xi**2)
        
        steps = f"""
    COROTATION RESONANCE PARAMETER
    ══════════════════════════════════════════════════════════════════
    
    ξ = (r - r_co) / r_co
    S = 1 / (1 + |ξ|²)
    
    PARAMETERS:
        r = {r_kpc:.2f} kpc
        r_corotation = {self.r_co:.2f} kpc
    
    CALCULATION:
        ξ = ({r_kpc:.2f} - {self.r_co:.2f}) / {self.r_co:.2f}
          = {xi:.4f}
        
        S = 1 / (1 + ({xi:.4f})²)
          = {S:.4f}
    
    INTERPRETATION:
        ξ = 0 → exact corotation
        S = 1 → perfect stability
        
        {'NEAR COROTATION: Minimal arm crossing rate' if abs(xi) < 0.2 else 'OFF COROTATION: Frequent arm crossings'}
    ══════════════════════════════════════════════════════════════════"""
        
        return xi, S, steps
    
    def compute_arm_crossing_rate(self, r_kpc: float = None) -> Tuple[float, str]:
        """
        Compute spiral arm crossing rate.
        
        Rate ∝ |v_star - v_pattern|
        
        Args:
            r_kpc: Radius (kpc)
        
        Returns:
            rate: Arm crossings per Gyr
            steps: Derivation string
        """
        r_kpc = r_kpc if r_kpc is not None else self.r_sun_kpc
        
        # Circular velocity (flat rotation curve)
        v_star = self.v_sun  # km/s
        
        # Pattern velocity at r
        v_pattern = self.Omega_pattern * r_kpc  # km/s
        
        # Relative velocity
        v_rel = abs(v_star - v_pattern)
        
        # Arm width ~ 1 kpc, 4 arms
        arm_width_kpc = 1.0
        kpc = 3.086e19  # m
        
        # Time to cross one arm
        t_cross_s = arm_width_kpc * kpc / (v_rel * 1e3) if v_rel > 0 else float('inf')
        t_cross_Gyr = t_cross_s / (3.15e7 * 1e9)
        
        # Crossing rate (4 arms per orbit, accounting for pattern motion)
        rate = 4 / t_cross_Gyr if t_cross_Gyr < float('inf') else 0
        
        steps = f"""
    SPIRAL ARM CROSSING RATE
    ══════════════════════════════════════════════════════════════════
    
    Rate ∝ |v_star - v_pattern|
    
    VELOCITIES:
        r = {r_kpc:.2f} kpc
        v_star = {v_star:.0f} km/s (circular)
        v_pattern = Ω_p × r = {self.Omega_pattern} × {r_kpc:.2f} = {v_pattern:.0f} km/s
        
        |v_rel| = |{v_star:.0f} - {v_pattern:.0f}| = {v_rel:.0f} km/s
    
    ARM CROSSING TIME:
        arm_width ≈ 1 kpc
        t_cross = 1 kpc / {v_rel:.0f} km/s = {t_cross_Gyr * 1000:.1f} Myr
    
    CROSSING RATE:
        4 arms per orbit cycle
        Rate ≈ {rate:.2f} crossings/Gyr
    
    SUN'S ADVANTAGE:
        Near corotation → low v_rel → few crossings
        → Less exposure to arm-triggered supernovae
        → More stable climate for Earth
    ══════════════════════════════════════════════════════════════════"""
        
        return rate, steps
    
    def compute_habitability_factor(self, r_kpc: float = None) -> Tuple[float, str]:
        """
        Compute habitability factor based on corotation and metallicity.
        
        H = S × Z(r)/Z_sun × (1 if r in GHZ else 0)
        
        Args:
            r_kpc: Radius (kpc)
        
        Returns:
            H: Habitability factor (0-1)
            steps: Derivation string
        """
        r_kpc = r_kpc if r_kpc is not None else self.r_sun_kpc
        
        # Stability from corotation
        xi, S, _ = self.compute_resonance_parameter(r_kpc)
        
        # Metallicity factor
        Z_0 = 0.03  # Central metallicity
        Z_sun = 0.0134
        r_Z = 8.0  # Scale length
        Z_r = Z_0 * np.exp(-r_kpc / r_Z)
        Z_factor = Z_r / Z_sun
        
        # In GHZ?
        in_GHZ = self.r_GHZ_inner <= r_kpc <= self.r_GHZ_outer
        
        # Combined habitability
        H = S * min(Z_factor, 1.0) * (1 if in_GHZ else 0.1)
        
        steps = f"""
    GALACTIC HABITABILITY FACTOR
    ══════════════════════════════════════════════════════════════════
    
    H = S × min(Z/Z_sun, 1) × GHZ_factor
    
    COMPONENTS:
        r = {r_kpc:.2f} kpc
        
        Stability (S):
            ξ = {xi:.4f}
            S = {S:.4f}
        
        Metallicity:
            Z(r) = {Z_r:.4f}
            Z_sun = {Z_sun}
            Z/Z_sun = {Z_factor:.4f}
        
        Galactic Habitable Zone:
            GHZ = [{self.r_GHZ_inner}, {self.r_GHZ_outer}] kpc
            r = {r_kpc:.2f} kpc → {'IN GHZ ✓' if in_GHZ else 'OUTSIDE GHZ'}
    
    HABITABILITY:
        H = {S:.4f} × {min(Z_factor, 1.0):.4f} × {1 if in_GHZ else 0.1}
          = {H:.4f}
    
    SUN'S POSITION OPTIMALITY:
        - Near corotation (S ≈ 0.99) → stable
        - Moderate metallicity → planets possible
        - In GHZ → not too hot/cold
        → H ≈ {H:.4f} {'(highly habitable)' if H > 0.8 else '(moderately habitable)' if H > 0.5 else '(less habitable)'}
    ══════════════════════════════════════════════════════════════════"""
        
        return H, steps
    
