class GravitationalTimeDilationModel(SelfSimulatingExpandingMixin):
    """
    Gravitational Time Dilation Model - GR Time Effects
    
    Models the slowing of time in gravitational fields, essential for
    understanding dynamics near SMBHs and compact objects.
    
    KEY EQUATION:
    ─────────────────────────────────────────────────────────────────────────────
    
    t' = t₀ × √(1 - 2GM/(rc²))
    
    Where:
        t' : Proper time experienced in gravitational field (s)
        t₀ : Coordinate time in flat spacetime (s)
        G : Gravitational constant (6.674 × 10⁻¹¹ m³ kg⁻¹ s⁻²)
        M : Mass of gravitating body (kg)
        r : Distance from center of mass (m)
        c : Speed of light (2.998 × 10⁸ m/s)
    
    PHYSICAL INTERPRETATION:
    ─────────────────────────────────────────────────────────────────────────────
    
    - Time runs slower in stronger gravitational fields
    - At r = r_s (Schwarzschild radius): time stops (event horizon)
    - Far from mass: t' → t₀ (flat spacetime)
    
    APPLICATIONS:
    ─────────────────────────────────────────────────────────────────────────────
    
    - GPS satellite corrections (~45 μs/day faster)
    - Black hole accretion disk observations
    - Gravitational wave source timing
    - SMBH dynamics near event horizon
    
    ©2025 Daniel T. Murphy - All Rights Reserved
    """
    
    def __init__(self):
        self.G = 6.674e-11         # Gravitational constant (m³ kg⁻¹ s⁻²)
        self.c = 2.998e8           # Speed of light (m/s)
        self.M_sun = 1.989e30      # Solar mass (kg)
        
    def compute_time_dilation(self, t0: float, M: float, r: float) -> Tuple[float, str]:
        """
        Compute proper time in gravitational field.
        
        Args:
            t0: Coordinate time (s)
            M: Mass of gravitating body (kg)
            r: Distance from center (m)
            
        Returns:
            t_proper: Proper time experienced (s)
            steps: Calculation explanation
        """
        import math
        
        # Schwarzschild radius
        r_s = 2 * self.G * M / self.c**2
        
        if r <= r_s:
            raise ValueError(f"r = {r} m ≤ r_s = {r_s} m: inside event horizon")
        
        # Time dilation factor
        gamma = math.sqrt(1 - r_s / r)
        t_proper = t0 * gamma
        
        steps = f"""Gravitational Time Dilation:
  
  t' = t₀ × √(1 - 2GM/(rc²)) = t₀ × √(1 - r_s/r)
  
  Parameters:
    M = {M:.4e} kg = {M/self.M_sun:.2f} M_☉
    r = {r:.4e} m
    t₀ = {t0:.6f} s
    
  Schwarzschild radius:
    r_s = 2GM/c² = {r_s:.4e} m
    r/r_s = {r/r_s:.2f}
  
  Time dilation factor:
    γ = √(1 - r_s/r) = √(1 - {r_s/r:.6f}) = {gamma:.6f}
  
  Result:
    t' = {t0:.6f} × {gamma:.6f} = {t_proper:.6f} s
    
  Time runs {(1-gamma)*100:.4f}% slower at r = {r:.4e} m
"""
        return t_proper, steps
    
    def compute_dilation_factor(self, M: float, r: float) -> Tuple[float, str]:
        """
        Compute time dilation factor γ = √(1 - r_s/r).
        
        Args:
            M: Mass (kg)
            r: Distance (m)
            
        Returns:
            gamma: Time dilation factor [0, 1]
            steps: Calculation explanation
        """
        import math
        
        r_s = 2 * self.G * M / self.c**2
        
        if r <= r_s:
            gamma = 0.0
            steps = f"r ≤ r_s = {r_s:.4e} m: γ = 0 (event horizon or interior)"
        else:
            gamma = math.sqrt(1 - r_s / r)
            steps = f"""Time Dilation Factor:
  
  γ = √(1 - r_s/r)
  r_s = 2GM/c² = {r_s:.4e} m
  γ = √(1 - {r_s:.4e}/{r:.4e}) = {gamma:.6f}
  
  Clock at r runs at {gamma*100:.4f}% of rate at infinity.
"""
        return gamma, steps
    
    def compute_GPS_correction(self) -> Tuple[float, str]:
        """
        Compute GPS time dilation correction.
        
        Returns:
            delta_t: Time gained per day (s)
            steps: Calculation explanation
        """
        import math
        
        M_earth = 5.972e24      # kg
        r_surface = 6.371e6     # m (Earth surface)
        r_GPS = 26.56e6         # m (GPS orbital radius)
        day_seconds = 86400     # s
        
        gamma_surface = math.sqrt(1 - 2*self.G*M_earth/(r_surface*self.c**2))
        gamma_GPS = math.sqrt(1 - 2*self.G*M_earth/(r_GPS*self.c**2))
        
        # GPS clock runs faster due to weaker gravity
        delta_gamma = gamma_GPS - gamma_surface
        delta_t = delta_gamma * day_seconds
        
        # Convert to microseconds
        delta_t_us = delta_t * 1e6
        
        steps = f"""GPS Gravitational Time Correction:
  
  Earth surface: r = {r_surface:.4e} m, γ = {gamma_surface:.10f}
  GPS orbit: r = {r_GPS:.4e} m, γ = {gamma_GPS:.10f}
  
  Δγ = γ_GPS - γ_surface = {delta_gamma:.4e}
  Δt/day = Δγ × 86400 s = {delta_t_us:.2f} μs
  
  GPS clocks run ~{delta_t_us:.1f} μs faster per day (gravity only).
  (Special relativistic correction: -7.2 μs/day)
  Net correction: ~38 μs/day
"""
        return delta_t_us, steps
    
    def validate_model(self) -> Tuple[bool, List[str], str]:
        """Validate Gravitational Time Dilation Model."""
        import math
        tests = []
        all_passed = True
        
        # Test 1: Far from mass, γ → 1
        gamma_far, _ = self.compute_dilation_factor(self.M_sun, 1e15)
        t1 = abs(gamma_far - 1.0) < 1e-6
        tests.append(f"Test 1: γ(r=1e15 m) = {gamma_far:.8f} ≈ 1: {'PASS' if t1 else 'FAIL'}")
        all_passed &= t1
        
        # Test 2: At 10 r_s, γ ≈ 0.949
        M_test = 10 * self.M_sun
        r_s = 2 * self.G * M_test / self.c**2
        gamma_10rs, _ = self.compute_dilation_factor(M_test, 10 * r_s)
        t2 = abs(gamma_10rs - math.sqrt(0.9)) < 0.01
        tests.append(f"Test 2: γ(r=10 r_s) = {gamma_10rs:.4f} ≈ √0.9 = 0.949: {'PASS' if t2 else 'FAIL'}")
        all_passed &= t2
        
        # Test 3: GPS correction in correct range (38-50 μs)
        delta_GPS, _ = self.compute_GPS_correction()
        t3 = 40 < delta_GPS < 50
        tests.append(f"Test 3: GPS correction = {delta_GPS:.2f} μs ∈ [40, 50]: {'PASS' if t3 else 'FAIL'}")
        all_passed &= t3
        
        # Test 4: Time dilation computation
        t_proper, _ = self.compute_time_dilation(1.0, self.M_sun, 1e9)
        t4 = 0.99 < t_proper < 1.0
        tests.append(f"Test 4: t'(1s, M_☉, 1e9 m) = {t_proper:.8f} s < 1: {'PASS' if t4 else 'FAIL'}")
        all_passed &= t4
        
        summary = f"GravitationalTimeDilationModel: {sum(1 for t in tests if 'PASS' in t)}/4 tests passed"
        return all_passed, tests, summary

    @staticmethod
    def run_tests() -> dict:
        """Test GravitationalTimeDilationModel functionality."""
        tests = []
        try:
            model = GravitationalTimeDilationModel()
            tests.append({'name': 'Instantiation', 'passed': model is not None})
        except Exception as e:
            tests.append({'name': 'Instantiation', 'passed': False, 'error': str(e)})
        try:
            model = GravitationalTimeDilationModel()
            has_method = hasattr(model, 'compute') or hasattr(model, 'calculate') or hasattr(model, 'get_equation_text')
            tests.append({'name': 'Has compute method', 'passed': has_method})
        except Exception as e:
            tests.append({'name': 'Has compute method', 'passed': False, 'error': str(e)})
        all_passed = all(t['passed'] for t in tests)
        return {'class': 'GravitationalTimeDilationModel', 'tests': tests, 'passed': sum(1 for t in tests if t['passed']), 'total': len(tests), 'all_passed': all_passed}

