class EddingtonRatioModel(SelfSimulatingExpandingMixin):
    """
    Eddington Ratio Model - AGN Activity Indicator
    
    Models the distribution of Eddington ratios (λ = L/L_Edd) in AGN,
    indicating accretion activity levels.
    
    KEY EQUATIONS:
    ─────────────────────────────────────────────────────────────────────────────
    
    Eddington Luminosity:
    L_Edd = 4π × G × M × m_p × c / σ_T ≈ 1.26 × 10³⁸ × (M/M_☉) erg/s
    
    Eddington Ratio:
    λ = L_bol / L_Edd
    
    Distribution (log-normal):
    P(λ) ∝ exp(-(log λ - μ)² / (2σ²))
    
    Where:
        L_bol : Bolometric luminosity (erg/s)
        L_Edd : Eddington luminosity
        μ : Mean of log λ (typically -1 to -2)
        σ : Standard deviation (typically 0.3-0.5)
    
    PHYSICAL INTERPRETATION:
    ─────────────────────────────────────────────────────────────────────────────
    
    - λ = 1: Eddington-limited accretion (maximum sustainable)
    - λ ~ 0.1: Typical luminous AGN/quasar
    - λ ~ 0.01: Moderate AGN
    - λ << 0.01: Low-luminosity AGN (LLAGN), radiatively inefficient
    
    ©2025 Daniel T. Murphy - All Rights Reserved
    """
    
    def __init__(self):
        self.G = 6.674e-11         # Gravitational constant
        self.c = 2.998e8           # Speed of light
        self.M_sun = 1.989e30      # Solar mass
        self.m_p = 1.673e-27       # Proton mass
        self.sigma_T = 6.652e-29   # Thomson cross section (m²)
        
        # Distribution parameters (typical for AGN)
        self.mu_log_lambda = -1.0   # Mean log λ (λ ~ 0.1)
        self.sigma_log_lambda = 0.4 # Dispersion
        
    def compute_eddington_luminosity(self, M: float) -> Tuple[float, str]:
        """
        Compute Eddington luminosity.
        
        Args:
            M: Black hole mass (kg)
            
        Returns:
            L_Edd: Eddington luminosity (erg/s)
            steps: Calculation explanation
        """
        # L_Edd = 4π × G × M × m_p × c / σ_T
        L_Edd_W = 4 * 3.14159 * self.G * M * self.m_p * self.c / self.sigma_T
        L_Edd = L_Edd_W * 1e7  # Convert W to erg/s
        
        steps = f"""Eddington Luminosity:
  
  L_Edd = 4π G M m_p c / σ_T
  
  Parameters:
    M = {M:.4e} kg = {M/self.M_sun:.2e} M_☉
  
  Result:
    L_Edd = {L_Edd_W:.4e} W = {L_Edd:.4e} erg/s
    
  Shortcut: L_Edd ≈ 1.26 × 10³⁸ × (M/M_☉) erg/s
            L_Edd ≈ {1.26e38 * M/self.M_sun:.4e} erg/s
"""
        return L_Edd, steps
    
    def compute_eddington_ratio(self, L_bol: float, M: float) -> Tuple[float, str]:
        """
        Compute Eddington ratio.
        
        Args:
            L_bol: Bolometric luminosity (erg/s)
            M: Black hole mass (kg)
            
        Returns:
            lambda_Edd: Eddington ratio
            steps: Calculation explanation
        """
        L_Edd, _ = self.compute_eddington_luminosity(M)
        lambda_Edd = L_bol / L_Edd
        
        if lambda_Edd > 1:
            classification = "Super-Eddington (radiation pressure dominated)"
        elif lambda_Edd > 0.1:
            classification = "High accretion rate (luminous AGN/quasar)"
        elif lambda_Edd > 0.01:
            classification = "Moderate AGN"
        elif lambda_Edd > 0.001:
            classification = "Low-luminosity AGN (LLAGN)"
        else:
            classification = "Radiatively inefficient (ADAF/RIAF)"
        
        steps = f"""Eddington Ratio:
  
  λ = L_bol / L_Edd
  
  Parameters:
    L_bol = {L_bol:.4e} erg/s
    L_Edd = {L_Edd:.4e} erg/s
  
  Result:
    λ = {lambda_Edd:.4e}
    log λ = {lambda_Edd:.4e} → log₁₀ = {__import__('math').log10(lambda_Edd) if lambda_Edd > 0 else float('-inf'):.2f}
  
  Classification: {classification}
"""
        return lambda_Edd, steps
    
    def compute_distribution_probability(self, lambda_Edd: float) -> Tuple[float, str]:
        """
        Compute probability density from log-normal distribution.
        
        Args:
            lambda_Edd: Eddington ratio
            
        Returns:
            P: Probability density
            steps: Calculation explanation
        """
        import math
        
        if lambda_Edd <= 0:
            return 0.0, "λ ≤ 0: P = 0"
        
        log_lambda = math.log10(lambda_Edd)
        exponent = -(log_lambda - self.mu_log_lambda)**2 / (2 * self.sigma_log_lambda**2)
        P = math.exp(exponent) / (lambda_Edd * self.sigma_log_lambda * math.sqrt(2*math.pi))
        
        steps = f"""Log-Normal Distribution:
  
  P(λ) ∝ exp(-(log λ - μ)² / (2σ²))
  
  Parameters:
    λ = {lambda_Edd:.4e}
    log₁₀ λ = {log_lambda:.2f}
    μ = {self.mu_log_lambda} (peak at λ ~ 0.1)
    σ = {self.sigma_log_lambda}
  
  Result:
    P(λ) = {P:.4e}
"""
        return P, steps
    
    def compute_eddington_rate(self, M: float, epsilon: float = 0.1) -> Tuple[float, str]:
        """
        Compute Eddington accretion rate.
        
        Args:
            M: Black hole mass (kg)
            epsilon: Radiative efficiency
            
        Returns:
            M_dot_Edd: Eddington rate (M_☉/yr)
            steps: Calculation explanation
        """
        L_Edd, _ = self.compute_eddington_luminosity(M)
        
        # Ṁ_Edd = L_Edd / (ε c²)
        L_Edd_W = L_Edd / 1e7  # to Watts
        M_dot_Edd_SI = L_Edd_W / (epsilon * self.c**2)
        M_dot_Edd = M_dot_Edd_SI * 3.156e7 / self.M_sun  # to M_☉/yr
        
        steps = f"""Eddington Accretion Rate:
  
  Ṁ_Edd = L_Edd / (ε c²)
  
  Parameters:
    M = {M/self.M_sun:.2e} M_☉
    L_Edd = {L_Edd:.4e} erg/s
    ε = {epsilon}
  
  Result:
    Ṁ_Edd = {M_dot_Edd:.4e} M_☉/yr
"""
        return M_dot_Edd, steps
    
    def validate_model(self) -> Tuple[bool, List[str], str]:
        """Validate Eddington Ratio Model."""
        import math
        tests = []
        all_passed = True
        
        # Test 1: L_Edd for 10⁸ M_☉ ~ 10⁴⁶ erg/s
        L_Edd, _ = self.compute_eddington_luminosity(1e8 * self.M_sun)
        t1 = 1e45 < L_Edd < 1e47
        tests.append(f"Test 1: L_Edd(10⁸ M_☉) = {L_Edd:.2e} ∈ [10⁴⁵, 10⁴⁷]: {'PASS' if t1 else 'FAIL'}")
        all_passed &= t1
        
        # Test 2: λ = 1 for L = L_Edd
        M_test = 1e7 * self.M_sun
        L_Edd_test, _ = self.compute_eddington_luminosity(M_test)
        lambda_test, _ = self.compute_eddington_ratio(L_Edd_test, M_test)
        t2 = abs(lambda_test - 1.0) < 0.01
        tests.append(f"Test 2: λ(L=L_Edd) = {lambda_test:.4f} ≈ 1: {'PASS' if t2 else 'FAIL'}")
        all_passed &= t2
        
        # Test 3: Distribution peaks near λ ~ 0.1
        P_peak, _ = self.compute_distribution_probability(0.1)
        P_low, _ = self.compute_distribution_probability(0.001)
        t3 = P_peak > P_low
        tests.append(f"Test 3: P(λ=0.1) > P(λ=0.001): {'PASS' if t3 else 'FAIL'}")
        all_passed &= t3
        
        # Test 4: Eddington rate physical
        M_dot, _ = self.compute_eddington_rate(1e8 * self.M_sun)
        t4 = 1 < M_dot < 100
        tests.append(f"Test 4: Ṁ_Edd(10⁸ M_☉) = {M_dot:.2f} M_☉/yr ∈ [1, 100]: {'PASS' if t4 else 'FAIL'}")
        all_passed &= t4
        
        summary = f"EddingtonRatioModel: {sum(1 for t in tests if 'PASS' in t)}/4 tests passed"
        return all_passed, tests, summary

    @staticmethod
    def run_tests() -> dict:
        """Test EddingtonRatioModel functionality."""
        tests = []
        try:
            model = EddingtonRatioModel()
            tests.append({'name': 'Instantiation', 'passed': model is not None})
        except Exception as e:
            tests.append({'name': 'Instantiation', 'passed': False, 'error': str(e)})
        try:
            model = EddingtonRatioModel()
            has_method = hasattr(model, 'compute') or hasattr(model, 'calculate') or hasattr(model, 'get_equation_text')
            tests.append({'name': 'Has compute method', 'passed': has_method})
        except Exception as e:
            tests.append({'name': 'Has compute method', 'passed': False, 'error': str(e)})
        all_passed = all(t['passed'] for t in tests)
        return {'class': 'EddingtonRatioModel', 'tests': tests, 'passed': sum(1 for t in tests if t['passed']), 'total': len(tests), 'all_passed': all_passed}

    # === 8 UQFF MASTER EQUATIONS (Auto-added) ===
    
    def compute_UQFF_base(self, r=None, t=0):
        """UQFF Base: F_U = Ug1 + Ug2 + Ug3 + Ug4 - Ub + Ui"""
        import numpy as np
        G = 6.674e-11
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        Ug = G * M / r**2
        return {'Ug': Ug, 'F_U': Ug, 'equation': f"F_U = G*M/r^2 = {Ug:.3e} m/s^2"}
    
    def compute_compressed_equation(self, r=None):
        """Compressed MUGE gravity equation"""
        import numpy as np
        G, H_0 = 6.674e-11, 2.268e-18
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        g_N = G * M / r**2
        g_H = H_0**2 * r
        g = g_N - g_H
        return {'g_compressed': g, 'g_N': g_N, 'g_Hubble': g_H}
    
    def compute_resonance_equation(self, r=None, t=0):
        """Resonance MUGE with frequency modes"""
        import numpy as np
        G, H_0, c = 6.674e-11, 2.268e-18, 2.998e8
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        aDPM = G * M / r**2
        aExpFreq = H_0 * c * np.sin(H_0 * t)
        return {'g_resonance': aDPM + aExpFreq, 'aDPM': aDPM, 'aExpFreq': aExpFreq}
    
    def compute_superconductive_equation(self, T=None, T_c=None):
        """Superconductive coefficient H_SCm"""
        T = T if T else getattr(self, 'T', 4.2)
        T_c = T_c if T_c else getattr(self, 'T_c', 9.2)
        H_SCm = max(0, 1 - (T / T_c)**4) if T < T_c else 0
        return {'H_SCm': H_SCm, 'T': T, 'T_c': T_c}
    
    def compute_buoyant_equation(self, r=None, V=None):
        """Buoyancy component Ub"""
        import numpy as np
        G, rho_vac = 6.674e-11, 7.09e-36
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        if V is None: V = (4/3) * np.pi * r**3
        g = G * M / r**2
        Ub = (rho_vac * V * g) / M
        return {'Ub': Ub, 'g': g, 'V': V}
    
    def compute_master_buoyant_equation(self, r=None, v=0):
        """Master Buoyant: F_U_Bi_i = M * (Ug_i - Ub_i + Ui_i)"""
        import numpy as np
        G, rho_vac, k_eta, c = 6.674e-11, 7.09e-36, 1e-113, 2.998e8
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        V = (4/3) * np.pi * r**3
        Ug = G * M / r**2
        Ub = (rho_vac * V * Ug) / M
        Ui = -k_eta * rho_vac * V * (v / c)**2
        a_net = Ug - Ub + Ui
        return {'F_U_Bi_i': M * a_net, 'Ug': Ug, 'Ub': Ub, 'Ui': Ui, 'a_net': a_net}
    
    def compute_triadic_equation(self, r=None):
        """Triadic gravity: g_matter + g_field + g_vacuum"""
        import numpy as np
        G = 6.674e-11
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        g_matter = G * M / r**2
        g_field, g_vacuum = 1e-15, 1e-20
        return {'g_triadic': g_matter + g_field + g_vacuum, 'g_matter': g_matter}
    
    def compute_quadratic_equation(self, r=None):
        """Quadratic polynomial fit: g = a*r^2 + b*r + c"""
        import numpy as np
        G = 6.674e-11
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        g_base = G * M / r**2
        a, b, c = -1e-30, 1e-20, g_base
        return {'g_quad': a * r**2 + b * r + c, 'a': a, 'b': b, 'c': c}

    def long_form_solution(self, r=None, t=0):
        """
        Long-form solution with complete equation display.
        Returns detailed step-by-step calculation for all UQFF equations.
        """
        import numpy as np
        G = 6.674e-11
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None:
            r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        
        # Collect all equation results
        results = {}
        steps = []
        
        # 1. UQFF Base
        uqff = self.compute_UQFF_base(r, t)
        results['UQFF_base'] = uqff
        steps.append(f"UQFF Base: F_U = G*M/r^2 = {uqff['Ug']:.6e} m/s^2")
        
        # 2. Compressed equation
        comp = self.compute_compressed_equation(r)
        results['compressed'] = comp
        steps.append(f"Compressed: g = g_N - g_H = {comp['g_compressed']:.6e} m/s^2")
        
        # 3. Resonance equation
        res = self.compute_resonance_equation(r, t)
        results['resonance'] = res
        steps.append(f"Resonance: g_res = aDPM + aExpFreq = {res['g_resonance']:.6e} m/s^2")
        
        # 4. Superconductive
        sc = self.compute_superconductive_equation()
        results['superconductive'] = sc
        steps.append(f"Superconductive: H_SCm = {sc['H_SCm']:.6f}")
        
        # 5. Buoyant equation
        buoy = self.compute_buoyant_equation(r)
        results['buoyant'] = buoy
        steps.append(f"Buoyancy: Ub = {buoy['Ub']:.6e} m/s^2")
        
        # 6. Master buoyant
        master = self.compute_master_buoyant_equation(r)
        results['master_buoyant'] = master
        steps.append(f"Master Buoyant: F_U_Bi_i = {master['F_U_Bi_i']:.6e} N")
        
        # 7. Triadic
        tri = self.compute_triadic_equation(r)
        results['triadic'] = tri
        steps.append(f"Triadic: g_triadic = {tri['g_triadic']:.6e} m/s^2")
        
        # 8. Quadratic
        quad = self.compute_quadratic_equation(r)
        results['quadratic'] = quad
        steps.append(f"Quadratic: g_quad = {quad['g_quad']:.6e} m/s^2")
        
        return {
            'model': self.__class__.__name__,
            'parameters': {'M': M, 'r': r, 't': t},
            'results': results,
            'long_form': '\n'.join(steps)
        }

    def compute_master_gravity(self, r=None, t=0, include_all=True):
        """
        Master Gravity: Complete UQFF gravity computation.
        
        g_master = g_N * (1 - Ub/g_N + Ui/g_N) * H_SCm * fTRZ
        
        Combines: Newtonian, buoyancy, inertia, superconductivity, triadic zone
        """
        import numpy as np
        G = 6.674e-11
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None:
            r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        
        # Base Newtonian gravity
        g_N = G * M / r**2
        
        # Get buoyancy correction
        buoy = self.compute_buoyant_equation(r)
        Ub = buoy['Ub']
        
        # Get superconductive coefficient
        sc = self.compute_superconductive_equation()
        H_SCm = sc['H_SCm']
        
        # Get triadic factor (default: in resonance zone)
        fTRZ = 1.0
        
        # Compute master gravity
        if g_N != 0:
            correction = 1 - Ub / g_N
        else:
            correction = 1.0
        
        g_master = g_N * correction * max(0.01, H_SCm) * fTRZ
        
        # Collect additional terms if requested
        if include_all:
            comp = self.compute_compressed_equation(r)
            res = self.compute_resonance_equation(r, t)
            tri = self.compute_triadic_equation(r)
            return {
                'g_master': g_master,
                'g_N': g_N,
                'Ub': Ub,
                'H_SCm': H_SCm,
                'fTRZ': fTRZ,
                'correction': correction,
                'g_compressed': comp['g_compressed'],
                'g_resonance': res['g_resonance'],
                'g_triadic': tri['g_triadic'],
                'equation': f"g_master = g_N * (1 - Ub/g_N) * H_SCm * fTRZ = {g_master:.6e} m/s^2"
            }
        
        return {'g_master': g_master, 'g_N': g_N}






class TidalDisruptionEventModel(SelfSimulatingExpandingMixin):
    """
    Tidal Disruption Event (TDE) Model
    
    Models the rate and properties of stars being torn apart by SMBHs,
    providing insights into SMBH properties and stellar dynamics.
    
    KEY EQUATIONS:
    ─────────────────────────────────────────────────────────────────────────────
    
    TDE Rate (Loss Cone Dynamics):
    Γ_TDE ≈ N_★ / τ_LC
    
    Where:
        N_★ : Number of stars in loss cone
        τ_LC : Loss cone refilling timescale
    
    Tidal Disruption Radius (from TidalForceModel):
    r_T = R_★ × (M_BH / M_★)^(1/3)
    
    Hills Mass (maximum BH mass for visible TDE):
    M_Hills ≈ 10⁸ M_☉ × (R_★/R_☉) × (M_★/M_☉)^(-1/3)
    
    OBSERVATIONAL PROPERTIES:
    ─────────────────────────────────────────────────────────────────────────────
    
    - Peak luminosity: L_peak ~ 10⁴⁴ erg/s (Eddington for 10⁶ M_☉)
    - Timescale: t_decay ∝ t^(-5/3) (fallback rate)
    - Rate: Γ_TDE ~ 10⁻⁴ - 10⁻⁵ per galaxy per year
    
    ©2025 Daniel T. Murphy - All Rights Reserved
    """
    
    def __init__(self):
        self.G = 6.674e-11         # Gravitational constant
        self.c = 2.998e8           # Speed of light
        self.M_sun = 1.989e30      # Solar mass
        self.R_sun = 6.96e8        # Solar radius (m)
        
    def compute_disruption_radius(self, M_BH: float, M_star: float = None, 
                                   R_star: float = None) -> Tuple[float, str]:
        """
        Compute tidal disruption radius.
        
        Args:
            M_BH: Black hole mass (kg)
            M_star: Stellar mass (kg)
            R_star: Stellar radius (m)
            
        Returns:
            r_T: Disruption radius (m)
            steps: Calculation explanation
        """
        if M_star is None:
            M_star = self.M_sun
        if R_star is None:
            R_star = self.R_sun
            
        r_T = R_star * (M_BH / M_star) ** (1/3)
        r_s = 2 * self.G * M_BH / self.c**2
        
        steps = f"""Tidal Disruption Radius:
  
  r_T = R_★ × (M_BH / M_★)^(1/3)
  
  Parameters:
    M_BH = {M_BH/self.M_sun:.2e} M_☉
    M_★ = {M_star/self.M_sun:.2f} M_☉
    R_★ = {R_star/self.R_sun:.2f} R_☉
  
  Result:
    r_T = {r_T:.4e} m = {r_T/1.496e11:.4f} AU
    r_s = {r_s:.4e} m
    r_T/r_s = {r_T/r_s:.2f}
    
  {'Visible TDE: star disrupted outside horizon' if r_T > r_s else 'Direct capture: star swallowed whole'}
"""
        return r_T, steps
    
    def compute_hills_mass(self, M_star: float = None, R_star: float = None) -> Tuple[float, str]:
        """
        Compute Hills mass - maximum BH mass for visible TDE.
        
        Args:
            M_star: Stellar mass (kg)
            R_star: Stellar radius (m)
            
        Returns:
            M_Hills: Hills mass (kg)
            steps: Calculation explanation
        """
        if M_star is None:
            M_star = self.M_sun
        if R_star is None:
            R_star = self.R_sun
            
        # M_Hills ≈ 10⁸ M_☉ for solar-type star
        # Derived from r_T = r_s condition
        # M_Hills = (c²R_★/(2G))^(3/2) × M_★^(-1/2)
        M_Hills = (self.c**2 * R_star / (2 * self.G))**(3/2) * M_star**(-1/2)
        
        steps = f"""Hills Mass (Maximum for Visible TDE):
  
  M_Hills: r_T = r_s condition
  M_Hills = (c²R_★/2G)^(3/2) × M_★^(-1/2)
  
  Parameters:
    M_★ = {M_star/self.M_sun:.2f} M_☉
    R_★ = {R_star/self.R_sun:.2f} R_☉
  
  Result:
    M_Hills = {M_Hills:.4e} kg = {M_Hills/self.M_sun:.2e} M_☉
    
  For M_BH > M_Hills: star captured whole, no flare.
  For M_BH < M_Hills: visible TDE with optical/X-ray emission.
"""
        return M_Hills, steps
    
    def compute_TDE_rate(self, M_BH: float, sigma: float = 100e3) -> Tuple[float, str]:
        """
        Estimate TDE rate from velocity dispersion.
        
        Args:
            M_BH: Black hole mass (kg)
            sigma: Velocity dispersion (m/s)
            
        Returns:
            Gamma_TDE: TDE rate (per year)
            steps: Calculation explanation
        """
        import math
        
        # Loss cone theory: Γ ∝ (M_BH)^(-0.4) approximately
        # Empirical calibration: ~10⁻⁴ yr⁻¹ for 10⁶-10⁷ M_☉
        M_BH_6 = M_BH / (1e6 * self.M_sun)
        
        # Rate scaling from simulations
        Gamma_TDE = 1e-4 * M_BH_6**(-0.4)
        
        # Apply Hills mass cutoff
        M_Hills, _ = self.compute_hills_mass()
        if M_BH > M_Hills:
            Gamma_TDE = 0.0
            note = "M_BH > M_Hills: Direct capture only, no visible TDE"
        else:
            note = f"Expect ~{Gamma_TDE * 1e4:.1f} TDEs per 10,000 years"
        
        steps = f"""TDE Rate Estimation:
  
  Γ_TDE ≈ 10⁻⁴ × (M_BH/10⁶ M_☉)^(-0.4) yr⁻¹
  
  Parameters:
    M_BH = {M_BH/self.M_sun:.2e} M_☉
    M_Hills = {M_Hills/self.M_sun:.2e} M_☉
  
  Result:
    Γ_TDE = {Gamma_TDE:.4e} yr⁻¹
    
  {note}
"""
        return Gamma_TDE, steps
    
    def compute_fallback_lightcurve(self, t: float, t_min: float = 1.0) -> Tuple[float, str]:
        """
        Compute normalized fallback rate (lightcurve shape).
        
        L(t) ∝ t^(-5/3) for t > t_min
        
        Args:
            t: Time since disruption (days)
            t_min: Minimum fallback time (days)
            
        Returns:
            L_norm: Normalized luminosity [0, 1]
            steps: Calculation explanation
        """
        if t < t_min:
            L_norm = (t / t_min)  # Rising phase
        else:
            L_norm = (t / t_min)**(-5/3)  # Fallback decay
        
        steps = f"""TDE Lightcurve (Fallback Rate):
  
  L(t) ∝ t^(-5/3) for t > t_min
  
  Parameters:
    t = {t:.1f} days
    t_min = {t_min:.1f} days (peak)
  
  Result:
    L/L_peak = {L_norm:.4f}
    
  The t^(-5/3) decay is characteristic of TDE fallback dynamics.
"""
        return L_norm, steps
    
