        tests.append(f"Test 4: Ug3(a=0.9) > Ug3(a=0.3): {'PASS' if t4 else 'FAIL'}")
        all_passed &= t4
        
        summary = f"SMBHUg3Model: {sum(1 for t in tests if 'PASS' in t)}/4 tests passed"
