    M_gas = M_gas_solar * M_sun       # 1.989e32 kg
    M_stars = M_stars_solar * M_sun   # 3.978e31 kg
    M_total = M_total_solar * M_sun   # 2.387e32 kg
    
    # Geometry and distance
    span_ly = 2.5                     # Full nebula span (light-years)
    r_half_ly = span_ly / 2           # Half-span = 1.25 ly
    r = r_half_ly * light_year        # 1.182e16 m
    distance_ly = 1500                # Distance (light-years)
    distance_m = distance_ly * light_year  # 1.419e19 m
    z_redshift = 0.0003               # Cosmological redshift
    
    # Gas and magnetic properties
    rho_gas = 1e-21                   # Gas density (kg/m³)
    B_field = 1e-5                    # Magnetic field (T)
    v_gas = 1e5                       # Gas velocity (m/s)
    
    # Sigma Orionis (erosion source star system)
    L_SigmaOrionis_solar = 1e5        # Sigma Orionis luminosity in L_☉
    L_SigmaOrionis = L_SigmaOrionis_solar * L_sun  # 3.826e31 W
    
    # Erosion dynamics
    tau_erode_Myr = 5.0               # Erosion timescale (Myr)
    tau_erode = tau_erode_Myr * 1e6 * 3.156e7  # 1.578e14 s
    E_0 = 0.2                         # Fractional erosion coefficient (20%)
    t_current_Myr = 1.0               # Current evolutionary stage (Myr)
    t_current = t_current_Myr * 1e6 * 3.156e7  # 3.156e13 s
    
    # Nebula lifetime
    lifetime_Myr_min = 5              # Minimum remaining lifetime (Myr)
    lifetime_Myr_max = 10             # Maximum remaining lifetime (Myr)
    
