    def __init__(self, M=None, M_galaxy=None, M_BH=None, r=None, r_BH=None, z=None,
                 t_age=None, rho_dust=None, v_orbit=None, B=None, f_TRZ=None,
                 N_globular=None, M_globular_avg=None):
        """
        Initialize Sombrero Galaxy Model with configurable parameters.
        
        Uses constants from CONSTANTS dict if not specified.
        
        Args:
            M: Total mass (galaxy + SMBH) in kg
            M_galaxy: Galaxy mass (excluding SMBH) in kg
            M_BH: SMBH mass in kg
            r: Half-diameter (characteristic radius) in m
            r_BH: SMBH influence scale radius in m
            z: Redshift
            t_age: Galaxy age in seconds
            rho_dust: Dust lane density in kg/m³
            v_orbit: Orbital velocity in m/s
            B: Galactic magnetic field in T
            f_TRZ: Time-reversal zone correction factor
            N_globular: Number of globular clusters
            M_globular_avg: Average globular cluster mass in kg
        """
        # Core physical constants
        self.G = CONSTANTS.get('G', 6.6743e-11)           # m³ kg⁻¹ s⁻²
        self.c = CONSTANTS.get('c', 2.998e8)              # m/s
        self.H_0 = CONSTANTS.get('H_0', 2.268e-18)        # s⁻¹ (70 km/s/Mpc)
        self.H_0_km_s_Mpc = 70.0                          # km/s/Mpc (for display)
        self.Omega_m = 0.3                                # Matter density parameter
        self.Omega_Lambda = 0.7                           # Dark energy density parameter
        
        # Vacuum density parameters (UA correction)
        self.rho_vac_UA = CONSTANTS.get('rho_vac_UA', 7.09e-36)   # J/m³
        self.rho_vac_SCm = CONSTANTS.get('rho_vac_SCm', 7.09e-37) # J/m³
        self.q_proton = 1.602e-19                         # Proton charge (C)
        self.m_proton = 1.673e-27                         # Proton mass (kg)
        
        # Sombrero Galaxy parameters (M104 / NGC 4594)
        self.M = M if M is not None else CONSTANTS.get('M104_M', 2.009e41)
        self.M_galaxy = M_galaxy if M_galaxy is not None else CONSTANTS.get('M104_M_galaxy', 1.989e41)
        self.M_BH = M_BH if M_BH is not None else CONSTANTS.get('M104_M_BH', 1.989e39)
        self.r = r if r is not None else CONSTANTS.get('M104_r', 2.36e20)
        self.r_BH = r_BH if r_BH is not None else CONSTANTS.get('M104_r_BH', 1e15)
        self.z = z if z is not None else CONSTANTS.get('M104_z', 0.0063)
        self.t_age = t_age if t_age is not None else CONSTANTS.get('M104_t_age', 3.156e17)
        self.rho_dust = rho_dust if rho_dust is not None else CONSTANTS.get('M104_rho_dust', 1e-20)
        self.v_orbit = v_orbit if v_orbit is not None else CONSTANTS.get('M104_v_orbit', 2e5)
        self.B = B if B is not None else CONSTANTS.get('M104_B', 1e-5)
        self.f_TRZ = f_TRZ if f_TRZ is not None else 0.1
        self.N_globular = N_globular if N_globular is not None else CONSTANTS.get('M104_N_globular', 2000)
        self.M_globular_avg = M_globular_avg if M_globular_avg is not None else CONSTANTS.get('M104_M_globular_avg', 1.989e35)
        
        # Document reference values (May 2025 UQFF Analysis)
        self.g_grav_doc = CONSTANTS.get('g_grav_M104', 2.408e-10)
        self.g_BH_doc = CONSTANTS.get('g_BH_M104', 1.327e-1)
        self.a_dust_doc = CONSTANTS.get('a_dust_M104', 4e-1)
        self.g_total_doc = CONSTANTS.get('g_M104_total', 5.351e-1)
        
    def compute_H_z(self, z=None):
        """
        Compute Hubble parameter at redshift z.
        
        H(z) = H_0 × √(Ω_m(1+z)³ + Ω_Λ)
        
        Args:
            z: Redshift (uses instance z if not specified)
            
        Returns:
            H(z) in s⁻¹
        """
        import math
        if z is None:
            z = self.z
        term = self.Omega_m * (1 + z)**3 + self.Omega_Lambda
        return self.H_0 * math.sqrt(term)
    
    def compute_hubble_correction(self, t=None, z=None):
        """
        Compute Hubble expansion correction factor.
        
        (1 + H(z)·t)
        
        Args:
            t: Time in seconds (uses instance t_age if not specified)
            z: Redshift (uses instance z if not specified)
            
        Returns:
            Hubble correction factor (dimensionless)
        """
        if t is None:
            t = self.t_age
        H_z = self.compute_H_z(z)
        return 1.0 + H_z * t
    
    def compute_g_grav(self, r=None, M=None):
        """
        Compute base galactic gravitational acceleration.
        
        g_grav = (G × M) / r²
        
        Args:
            r: Radius in m (uses instance r if not specified)
            M: Total mass in kg (uses instance M if not specified)
            
        Returns:
            g_grav in m/s²
        """
        if r is None:
            r = self.r
        if M is None:
            M = self.M
        return (self.G * M) / (r**2)
    
    def compute_g_BH(self, r_BH=None, M_BH=None):
        """
        Compute SMBH gravitational influence at core scale.
        
        g_BH = (G × M_BH) / r_BH²
        
        This represents the gravitational acceleration due to the supermassive
        black hole at its characteristic influence scale (~0.1 pc = 1e15 m).
        
        Args:
            r_BH: SMBH influence radius in m (uses instance r_BH if not specified)
            M_BH: SMBH mass in kg (uses instance M_BH if not specified)
            
        Returns:
            g_BH in m/s²
        """
        if r_BH is None:
            r_BH = self.r_BH
        if M_BH is None:
            M_BH = self.M_BH
        return (self.G * M_BH) / (r_BH**2)
    
    def compute_a_dust(self, rho_dust=None, v_orbit=None):
        """
        Compute dust lane dynamical friction acceleration.
        
        a_dust = ρ_dust × v_orbit² × scale_factor
        
        The Sombrero's prominent dust lane creates dynamical friction on
        orbiting material. Raw D_dust = ρ × v² gives N/m², converted to
        acceleration using ISM density ratio and macroscopic scale factor.
        
        Document derivation:
            D_dust = 10^-20 × (2e5)² = 4e-10 N/m²
            a_dust = D_dust / ρ_ISM × macro_scale
                   = 4e-10 / 10^-21 × 10^-12
                   = 4e11 × 10^-12 = 4e-1 m/s²
        
        Args:
            rho_dust: Dust density in kg/m³ (uses instance rho_dust if not specified)
            v_orbit: Orbital velocity in m/s (uses instance v_orbit if not specified)
            
        Returns:
            a_dust in m/s²
        """
        if rho_dust is None:
            rho_dust = self.rho_dust
        if v_orbit is None:
            v_orbit = self.v_orbit
        
        # Raw dynamical pressure: D_dust = ρ × v²
        D_dust = rho_dust * v_orbit**2  # 10^-20 × (2e5)² = 4e-10 N/m²
        
        # Convert to acceleration using ISM density and macroscopic scaling
        rho_ISM = 1e-21  # kg/m³ (ISM reference density)
        macro_scale = 1e-12  # Macroscopic scaling for galaxy-scale effects
        
        a_dust = (D_dust / rho_ISM) * macro_scale
        # = 4e-10 / 1e-21 * 1e-12 = 4e11 * 1e-12 = 4e-1
        
        return a_dust
    
    def compute_a_EM_with_UA(self, v=None, B=None):
        """
        Compute electromagnetic acceleration with UA correction.
        
        a_EM = q(v×B)(1 + ρ_UA/ρ_SCm) × macro_scale
        
        This term includes the magnetic Lorentz force on charged particles
        in the ISM, enhanced by the Aether [UA] correction factor.
        
        Document derivation:
            q(v×B) = 1.602e-19 × 2e5 × 10^-5 = 3.204e-19 N
            a = F/m = 3.204e-19 / 1.673e-27 = 1.915e8 m/s²
            UA correction = 1 + (7.09e-36 / 7.09e-37) = 11
            Raw a_EM = 1.915e8 × 11 = 2.107e9 m/s²
            Scaled a_EM = 2.107e9 × 10^-12 = 2.107e-3 m/s²
        
        Args:
            v: Velocity in m/s (uses instance v_orbit if not specified)
            B: Magnetic field in T (uses instance B if not specified)
            
        Returns:
            a_EM in m/s²
        """
        if v is None:
            v = self.v_orbit
        if B is None:
            B = self.B
        
        # Lorentz force on proton: F = q(v×B)
        F_lorentz = self.q_proton * v * B
        
        # Acceleration on proton: a = F/m
        a_raw = F_lorentz / self.m_proton
        
        # UA correction factor
        UA_factor = 1.0 + (self.rho_vac_UA / self.rho_vac_SCm)  # = 11
        
        # Apply UA correction
        a_corrected = a_raw * UA_factor
        
        # Macroscopic scaling for galaxy-scale effects
        macro_scale = 1e-12
        
        return a_corrected * macro_scale
    
    def compute_clean_equation(self, r=None, t=None, z=None):
        """
        Compute the clean UQFF master equation for Sombrero Galaxy evolution.
        
        g_Sombrero(r, t) = g_grav × (1 + H(z)·t) × (1 + f_TRZ) + g_BH + a_dust + a_EM
        
        This equation combines:
        - Gravitational base term with Hubble expansion and time-reversal corrections
        - SMBH gravitational influence at core
        - Dust lane dynamical friction
        - Electromagnetic effects with UA (Aether) correction
        
        Args:
            r: Radius in m (uses instance r if not specified)
            t: Time in seconds (uses instance t_age if not specified)
            z: Redshift (uses instance z if not specified)
            
        Returns:
            dict with all computed values and final g_Sombrero
        """
        if r is None:
            r = self.r
        if t is None:
            t = self.t_age
        if z is None:
            z = self.z
        
        # Base gravitational term
        g_grav = self.compute_g_grav(r)
        
        # Hubble expansion correction
        hubble_factor = self.compute_hubble_correction(t, z)
        
        # Time-reversal zone correction
        trz_factor = 1.0 + self.f_TRZ
        
        # Gravitational term with corrections
        g_grav_corrected = g_grav * hubble_factor * trz_factor
        
        # SMBH gravitational influence
        g_BH = self.compute_g_BH()
        
        # Dust lane dynamical friction
        a_dust = self.compute_a_dust()
        
        # Electromagnetic with UA correction
        a_EM = self.compute_a_EM_with_UA()
        
        # Final clean equation
        g_Sombrero = g_grav_corrected + g_BH + a_dust + a_EM
        
        # EM fraction (dominated by g_BH + a_dust)
        EM_fraction = (g_BH + a_dust) / g_Sombrero if g_Sombrero > 0 else 0.0
        
        return {
            'g_grav': g_grav,
            'hubble_factor': hubble_factor,
            'trz_factor': trz_factor,
            'g_grav_corrected': g_grav_corrected,
            'g_BH': g_BH,
            'a_dust': a_dust,
            'a_EM': a_EM,
            'g_Sombrero': g_Sombrero,
            'EM_fraction': EM_fraction,
            'breakdown': {
                'g_grav_pct': 100 * g_grav_corrected / g_Sombrero if g_Sombrero > 0 else 0,
                'g_BH_pct': 100 * g_BH / g_Sombrero if g_Sombrero > 0 else 0,
                'a_dust_pct': 100 * a_dust / g_Sombrero if g_Sombrero > 0 else 0,
                'a_EM_pct': 100 * a_EM / g_Sombrero if g_Sombrero > 0 else 0
            }
        }
    
    def compute_globular_cluster_mass(self):
        """
        Compute total globular cluster halo mass.
        
        M_globular_total = N × M_avg
        
        The Sombrero Galaxy has 2,000 globular clusters (2× Milky Way),
        indicating a dense, extended halo potentially influenced by
        the Virgo Cluster environment.
        
        Returns:
            dict with globular cluster properties
        """
        M_total = self.N_globular * self.M_globular_avg
        M_total_solar = M_total / 1.989e30  # Convert to solar masses
        
        # Fraction of total galaxy mass
        mass_fraction = M_total / self.M_galaxy
        
        return {
            'N_globular': self.N_globular,
            'M_avg_kg': self.M_globular_avg,
            'M_avg_solar': self.M_globular_avg / 1.989e30,
            'M_total_kg': M_total,
            'M_total_solar': M_total_solar,
            'mass_fraction': mass_fraction,
            'vs_milky_way': self.N_globular / 1000  # 2× Milky Way's ~1000 clusters
        }
    
    def compute_dust_lane_properties(self):
        """
        Compute comprehensive dust lane properties.
        
        The Sombrero's dust lane is one of its most distinctive features,
        affecting star formation and gas dynamics.
        
        Returns:
            dict with dust lane physical properties
        """
        import math
        # Mean free path in dust (simplified)
        sigma_dust = 1e-20  # m² (dust grain cross-section)
        n_dust = self.rho_dust / (1e-15)  # number density (assuming grain mass ~1e-15 kg)
        lambda_mfp = 1.0 / (n_dust * sigma_dust) if n_dust * sigma_dust > 0 else float('inf')
        
        # Optical depth estimate (simplified)
        dust_lane_thickness = 1e19  # m (rough estimate, ~1 kly)
        tau = n_dust * sigma_dust * dust_lane_thickness
        
        # Sound speed in dust/gas mixture (isothermal, T ~ 100 K)
        T_dust = 100  # K
        k_B = 1.381e-23  # J/K
        m_H = 1.673e-27  # kg (hydrogen mass)
        mu = 2.3  # Mean molecular weight
        c_s = math.sqrt(k_B * T_dust / (mu * m_H))
        
        # Jeans mass in dust lane
        M_jeans = (math.pi**(5/2) * c_s**3) / (6 * math.sqrt(self.G**3 * self.rho_dust))
        M_jeans_solar = M_jeans / 1.989e30
        
        return {
            'rho_dust': self.rho_dust,
            'v_orbit': self.v_orbit,
            'n_dust': n_dust,
            'lambda_mfp': lambda_mfp,
            'tau_optical': tau,
            'c_sound': c_s,
            'M_jeans_kg': M_jeans,
            'M_jeans_solar': M_jeans_solar
        }
    
    def compute_SMBH_properties(self):
        """
        Compute SMBH physical properties.
        
        The Sombrero's 1 billion M_sun SMBH is one of the largest
        in the nearby universe, exerting exceptional influence on
        the galactic core dynamics.
        
        Returns:
            dict with SMBH properties
        """
        import math
        # Schwarzschild radius
        r_s = (2 * self.G * self.M_BH) / (self.c**2)
        
        # Event horizon surface gravity
        g_horizon = self.c**4 / (4 * self.G * self.M_BH)
        
        # Eddington luminosity
        sigma_T = 6.652e-29  # Thomson cross-section (m²)
        L_edd = (4 * math.pi * self.G * self.M_BH * self.m_proton * self.c) / sigma_T
        L_edd_solar = L_edd / 3.828e26  # Convert to solar luminosities
        
        # Bondi accretion radius (approximate, using c_s ~ 100 km/s)
        c_s_bondi = 1e5  # m/s (sound speed in hot gas)
        r_bondi = (2 * self.G * self.M_BH) / (c_s_bondi**2)
        
        # SMBH mass relative to galaxy (M-sigma relation context)
        M_BH_fraction = self.M_BH / self.M_galaxy
        
        return {
            'M_BH_kg': self.M_BH,
            'M_BH_solar': self.M_BH / 1.989e30,
            'r_schwarzschild': r_s,
            'r_BH_influence': self.r_BH,
            'g_horizon': g_horizon,
            'L_eddington_W': L_edd,
            'L_eddington_solar': L_edd_solar,
            'r_bondi': r_bondi,
            'mass_fraction': M_BH_fraction
        }
    
    def validate_model(self):
        """
        Validate model outputs against document reference values.
        
        Returns:
            dict with validation results and pass/fail status
        """
        results = self.compute_clean_equation()
        
        # Compare to document values
        g_grav_ratio = results['g_grav'] / self.g_grav_doc if self.g_grav_doc != 0 else float('inf')
        g_BH_ratio = results['g_BH'] / self.g_BH_doc if self.g_BH_doc != 0 else float('inf')
        a_dust_ratio = results['a_dust'] / self.a_dust_doc if self.a_dust_doc != 0 else float('inf')
        g_total_ratio = results['g_Sombrero'] / self.g_total_doc if self.g_total_doc != 0 else float('inf')
        
        # Tolerance bounds (±1%)
        tol_low, tol_high = 0.99, 1.01
        
        validations = {
            'g_grav': {
                'computed': results['g_grav'],
                'document': self.g_grav_doc,
                'ratio': g_grav_ratio,
                'passed': tol_low <= g_grav_ratio <= tol_high
            },
            'g_BH': {
                'computed': results['g_BH'],
                'document': self.g_BH_doc,
                'ratio': g_BH_ratio,
                'passed': tol_low <= g_BH_ratio <= tol_high
            },
            'a_dust': {
                'computed': results['a_dust'],
                'document': self.a_dust_doc,
                'ratio': a_dust_ratio,
                'passed': tol_low <= a_dust_ratio <= tol_high
            },
            'g_Sombrero': {
                'computed': results['g_Sombrero'],
                'document': self.g_total_doc,
                'ratio': g_total_ratio,
                'passed': tol_low <= g_total_ratio <= tol_high
            }
        }
        
        all_passed = all(v['passed'] for v in validations.values())
        
        return {
            'validations': validations,
            'all_passed': all_passed,
            'computed_results': results
        }
    
