class MysticMountainModel(SelfSimulatingExpandingMixin):
    """
    Mystic Mountain (Carina Pillar) Model - UQFF Analysis
    
    Mystic Mountain - Star-Forming Pillar in Carina Nebula
    
    Mystic Mountain is a ~3 ly tall pillar of gas and dust in the Carina Nebula,
    located ~7,500 ly away. It features jets from newborn stars at its peak
    and is being eroded by radiation from nearby massive stars.
    
    KEY EQUATIONS:
    ─────────────────────────────────────────────────────────────────────────────
    
    Master Compressed UQFF Equation:
    g(r,t) = g_grav × (1+H(z)·t) × (1+M_sf) × (1-E_rad) × (1+f_TRZ) + a_EM
    
    Master Resonance UQFF Equation:
    R(t) = R_grav·cos(ω_grav·t) + R_jet·cos(ω_jet·t) × UA_factor × TRZ_factor
    
    Where:
        g_grav  = G·M/r²           Base gravitational acceleration
        M_sf(t) = SFR·t/M₀         Star formation mass growth
        E_rad(t)= E₀(1-e^(-t/τ))   Radiation erosion
        a_EM    = q(v×B)/m_p × UA  Electromagnetic with Aether correction
        ω_jet  = 1.989e-10 rad/s (Jet resonance)
    
    PHYSICAL PARAMETERS:
    ─────────────────────────────────────────────────────────────────────────────
        M           = 1.989e32 kg (1e+02 M_sun)
        r           = 1e16 m
        SFR         = 0.1 M_sun/yr
        B           = 1e-5 T
        z           = 0.0025
    
    APPLICATIONS:
    ─────────────────────────────────────────────────────────────────────────────
    
    - Protostellar jet physics
    - Pillar erosion dynamics
    - Triggered star formation
    - Photoevaporation modeling
    
    AUTHOR:
    ─────────────────────────────────────────────────────────────────────────────
    Copyright © Daniel T. Murphy, 2025
    Grok 3 DeepSearch analysis, May 2025
    Location: Youngstown, OH, USA (41.0997° N, 80.6495° W)
    """
    
    def __init__(self, M=None, r=None, SFR=None, v_wind=None, B=None,
                 rho_gas=None, t_age=None, z=None, f_TRZ=0.1, E_0=0.2, tau_erode=None):
        """
        Initialize Mystic Mountain (Carina Pillar) Model with configurable parameters.
        """
        import math
        
        # Physical constants
        self.G = 6.6743e-11         # Gravitational constant (m³/kg/s²)
        self.c = 2.998e8            # Speed of light (m/s)
        self.H_0 = 2.268e-18        # Hubble constant (s⁻¹)
        self.Omega_m = 0.3          # Matter density parameter
        self.Omega_Lambda = 0.7     # Dark energy density parameter
        self.q_e = 1.602e-19        # Electron charge (C)
        self.m_p = 1.673e-27        # Proton mass (kg)
        self.M_sun = 1.989e30       # Solar mass (kg)
        
        # UQFF vacuum densities
        self.rho_vac_UA = CONSTANTS.get('rho_vac_UA', 7.09e-36)
        self.rho_vac_SCm = CONSTANTS.get('rho_vac_SCm', 7.09e-37)
        
        # System parameters
        self.M = M if M is not None else CONSTANTS.get('MysticMountain_M', 1.989e32)
        self.r = r if r is not None else CONSTANTS.get('MysticMountain_r', 1e16)
        self.SFR = SFR if SFR is not None else CONSTANTS.get('MysticMountain_SFR', 0.1)
        self.SFR_kg_s = self.SFR * self.M_sun / (3.156e7)  # Convert to kg/s
        self.v_wind = v_wind if v_wind is not None else 1e6
        self.B = B if B is not None else CONSTANTS.get('MysticMountain_B', 1e-5)
        self.rho_gas = rho_gas if rho_gas is not None else CONSTANTS.get('MysticMountain_rho_gas', 1e-20)
        self.t_age = t_age if t_age is not None else CONSTANTS.get('MysticMountain_t_age', 6.31e13)
        self.z = z if z is not None else CONSTANTS.get('MysticMountain_z', 0.0025)
        self.f_TRZ = f_TRZ
        self.E_0 = E_0
        self.tau_erode = tau_erode if tau_erode is not None else 6.31e13  # 2 Myr default
        
        # Resonance timescales
        self.T_jet = 2 * math.pi / 1.989e-10
        self.omega_jet = 1.989e-10
    
    def compute_H_z(self):
        """Compute Hubble parameter at redshift z."""
        import math
        factor = self.Omega_m * (1 + self.z)**3 + self.Omega_Lambda
        return self.H_0 * math.sqrt(factor)
    
    def compute_hubble_correction(self, t=None):
        """Compute Hubble expansion correction factor (1 + H(z)·t)."""
        if t is None:
            t = self.t_age
        H_z = self.compute_H_z()
        return 1.0 + H_z * t
    
    def compute_g_grav(self, r=None):
        """Compute base gravitational acceleration g_grav = G·M/r²."""
        if r is None:
            r = self.r
        return self.G * self.M / (r * r)
    
    def compute_M_sf(self, t=None):
        """Compute star formation mass growth factor M_sf = SFR × t_Myr."""
        if t is None:
            t = self.t_age
        t_Myr = t / 3.156e13  # Convert to Myr
        return self.SFR * t_Myr
    
    def compute_E_rad(self, t=None):
        """Compute radiation erosion factor E_rad(t) = E₀(1 - e^(-t/τ))."""
        import math
        if t is None:
            t = self.t_age
        return self.E_0 * (1.0 - math.exp(-t / self.tau_erode))
    
    def compute_a_EM(self, v=None, B=None):
        """Compute electromagnetic acceleration with UQFF UA correction."""
        if v is None:
            v = self.v_wind
        if B is None:
            B = self.B
        
        # UA correction factor
        UA_factor = 1.0 + self.rho_vac_UA / self.rho_vac_SCm
        
        # Lorentz force on ion
        F_lorentz = self.q_e * v * B
        a_EM = (F_lorentz / self.m_p) * UA_factor * 1e-12  # Scaled
        
        return a_EM
    
    def compute_compressed_equation(self, t=None, r=None):
        """
        Compute Master Compressed UQFF equation.
        
        g(r,t) = g_grav × (1+H(z)·t) × (1+M_sf) × (1-E_rad) × (1+f_TRZ) + a_EM
        """
        if t is None:
            t = self.t_age
        if r is None:
            r = self.r
        
        # Components
        g_grav = self.compute_g_grav(r)
        hubble_factor = self.compute_hubble_correction(t)
        M_sf = self.compute_M_sf(t)
        M_sf_factor = 1.0 + M_sf
        E_rad = self.compute_E_rad(t)
        E_rad_factor = 1.0 - E_rad
        trz_factor = 1.0 + self.f_TRZ
        a_EM = self.compute_a_EM()
        
        # Gravitational term with corrections
        g_grav_corrected = g_grav * hubble_factor * M_sf_factor * E_rad_factor * trz_factor
        
        # Total compressed UQFF
        g_compressed = g_grav_corrected + a_EM
        
        # Dominance analysis
        EM_fraction = a_EM / g_compressed if g_compressed > 0 else 0.0
        
        return {
            'g_grav': g_grav,
            'hubble_factor': hubble_factor,
            'M_sf': M_sf,
            'M_sf_factor': M_sf_factor,
            'E_rad': E_rad,
            'E_rad_factor': E_rad_factor,
            'trz_factor': trz_factor,
            'g_grav_corrected': g_grav_corrected,
            'a_EM': a_EM,
            'g_compressed': g_compressed,
            'EM_fraction': EM_fraction
        }
    
    def compute_resonance_equation(self, t=None):
        """
        Compute Master Resonance UQFF equation.
        
        R(t) = R_grav·cos(ω_grav·t) + R_jet·cos(ω_jet·t) × UA_factor × TRZ_factor
        """
        import math
        if t is None:
            t = self.t_age
        
        # Angular frequencies
        omega_grav = 2 * math.pi / self.T_jet
        omega_jet = self.omega_jet
        
        # Gravitational resonance amplitude
        g_grav = self.compute_g_grav()
        M_sf = self.compute_M_sf(t)
        R_grav = g_grav * (1.0 + M_sf)
        
        # Jet resonance amplitude
        F_lorentz = self.q_e * self.v_wind * self.B
        R_jet_raw = F_lorentz / self.m_p
        R_jet = R_jet_raw * 1e-12
        
        # Correction factors
        UA_factor = 1.0 + self.rho_vac_UA / self.rho_vac_SCm
        TRZ_factor = 1.0 + self.f_TRZ
        
        # Oscillation phases
        phase_grav = omega_grav * t
        phase_jet = omega_jet * t
        
        # Resonance components
        R_grav_term = R_grav * math.cos(phase_grav)
        R_jet_term = R_jet * math.cos(phase_jet) * UA_factor * TRZ_factor
        
        # Total resonance
        R_total = R_grav_term + R_jet_term
        
        # Amplitude (non-oscillating)
        R_amplitude = abs(R_grav) + abs(R_jet * UA_factor * TRZ_factor)
        
        return {
            'omega_grav': omega_grav,
            'omega_jet': omega_jet,
            'R_grav': R_grav,
            'R_jet': R_jet,
            'UA_factor': UA_factor,
            'TRZ_factor': TRZ_factor,
            'R_grav_term': R_grav_term,
            'R_jet_term': R_jet_term,
            'R_total': R_total,
            'R_amplitude': R_amplitude
        }
    

    def compute_UQFF_base(self, t=None, r=None):
        """
        Compute UQFF Base Unified Field equation.
        
        F_U = Σ(Ug_i + Ub_i) + Um + Ur + Ut + Ui + UA + SCm
        
        This is the fundamental UQFF equation combining all field contributions.
        
        Returns:
            dict with all computed field values
        """
        import math
        if t is None:
            t = self.t_age
        if r is None:
            r = self.r
        
        # Gravitational terms
        g_grav = self.compute_g_grav(r)
        
        # Universal gravity components (26 layers simplified to primary terms)
        k_1, k_2, k_3, k_4 = 1.5, 1.2, 0.8, 0.5
        Ug1 = k_1 * g_grav                          # Magnetic dipole
        Ug2 = k_2 * g_grav * (1 + self.z)           # Charge-reactivity
        Ug3 = k_3 * g_grav * math.sin(2 * math.pi * t / self.t_age) if self.t_age > 0 else 0  # String rotation
        Ug4 = k_4 * g_grav * self.rho_vac_UA / 1e-36 if self.rho_vac_UA else k_4 * g_grav    # Vacuum concentration
        
        # Buoyancy term
        beta = CONSTANTS.get('beta_i', 0.6)
        Ub = beta * (g_grav - self.rho_vac_UA * self.G) if self.rho_vac_UA else beta * g_grav
        
        # Magnetism term
        Um = self.q_e * self.v_wind * self.B / self.m_p if hasattr(self, 'v_wind') else 0
        
        # Additional contributions (simplified)
        Ur = 0.01 * g_grav              # Radiation pressure
        Ut = 0.001 * g_grav             # Thermal contribution
        Ui = 0.0001 * g_grav            # Interstellar medium
        UA = self.rho_vac_UA * self.G * self.M / (r * r) if self.rho_vac_UA else 0
        SCm = self.rho_vac_SCm * self.G * self.M / (r * r) if self.rho_vac_SCm else 0
        
        # Total unified field
        F_U = Ug1 + Ug2 + Ug3 + Ug4 + Ub + Um + Ur + Ut + Ui + UA + SCm
        
        return {
            'F_U': F_U,
            'Ug1': Ug1,
            'Ug2': Ug2,
            'Ug3': Ug3,
            'Ug4': Ug4,
            'Ub': Ub,
            'Um': Um,
            'Ur': Ur,
            'Ut': Ut,
            'Ui': Ui,
            'UA': UA,
            'SCm': SCm,
            'g_grav': g_grav
        }
    
    def compute_superconductive_equation(self, t=None):
        """
        Compute UQFF Superconductive equation.
        
        [SCm](t) = [SCm]₀ × e^(-κt) × (1 - cos(ωt))
        
        Models SCm vacuum modulation over time.
        
        Returns:
            dict with superconductive field values
        """
        import math
        if t is None:
            t = self.t_age
        
        # UQFF calibrated constants
        kappa = CONSTANTS.get('kappa', 0.0005)      # Reactivity decay (day⁻¹)
        SSq = CONSTANTS.get('SSq', 0.57)            # Quantum state factor
        
        # Convert kappa from day⁻¹ to s⁻¹
        kappa_s = kappa / 86400
        
        # SCm base density
        SCm_0 = self.rho_vac_SCm if self.rho_vac_SCm else 7.09e-37
        
        # Angular frequency (based on characteristic timescale)
        omega_SCm = 2 * math.pi / (self.t_age if self.t_age > 0 else 1e13)
        
        # Exponential decay
        decay = math.exp(-kappa_s * t)
        
        # Oscillation factor
        oscillation = 1 - math.cos(omega_SCm * t)
        
        # SCm(t) modulation
        SCm_t = SCm_0 * decay * oscillation
        
        # Effective field contribution
        g_SCm = SCm_t * self.G * self.M / (self.r * self.r) if self.r > 0 else 0
        
        return {
            'SCm_t': SCm_t,
            'SCm_0': SCm_0,
            'decay_factor': decay,
            'oscillation_factor': oscillation,
            'g_SCm': g_SCm,
            'kappa': kappa,
            'omega_SCm': omega_SCm,
            'SSq': SSq
        }
    
    def compute_buoyant_equation(self, t=None, r=None):
        """
        Compute UQFF Buoyant equation (F_U_Bi).
        
        F_U_Bi = Σ β_i × (Ug_i - ρ_vac,i × G)
        
        Inside→Out atomic scale buoyancy (pushing outward).
        
        Returns:
            dict with buoyant field values
        """
        import math
        if t is None:
            t = self.t_age
        if r is None:
            r = self.r
        
        # Beta coupling factors
        beta = CONSTANTS.get('beta_i', 0.6)
        
        # Gravitational base
        g_grav = self.compute_g_grav(r)
        
        # Universal gravity components
        k_1 = 1.5
        Ug = k_1 * g_grav
        
        # Vacuum contribution
        rho_vac = self.rho_vac_UA if self.rho_vac_UA else 7.09e-36
        vac_term = rho_vac * self.G
        
        # Momentum term (electron pressure)
        m_e = CONSTANTS.get('m_e', 9.109e-31)
        c = self.c
        DPM_momentum = CONSTANTS.get('DPM_momentum', 1e-8)
        theta = math.pi / 4  # Default angle
        momentum_term = (m_e * c ** 2 / (r ** 2)) * DPM_momentum * math.cos(theta)
        
        # Gravity term
        DPM_gravity = CONSTANTS.get('DPM_gravity', 1e-10)
        gravity_term = g_grav * DPM_gravity
        
        # Buoyant fraction
        F_U_Bi = beta * (Ug - vac_term) + momentum_term + gravity_term
        
        return {
            'F_U_Bi': F_U_Bi,
            'beta': beta,
            'Ug': Ug,
            'vac_term': vac_term,
            'momentum_term': momentum_term,
            'gravity_term': gravity_term,
            'direction': 'Inside → Out',
            'scale': 'Atomic'
        }
    
    def compute_master_buoyant_equation(self, t=None):
        """
        Compute UQFF Master Buoyant equation (F_U_Bi_i).
        
        F_U_Bi_i = Ω_g × (M_bh/d_g) × Σ(Ug_i + Ub_i)
        
        Outside→In cosmic scale buoyancy (supporting from vacuum).
        
        Returns:
            dict with master buoyant field values
        """
        import math
        if t is None:
            t = self.t_age
        
        # Galactic parameters (defaults for star-forming regions)
        M_bh = CONSTANTS.get('M_bh_MW', 4e6 * self.M_sun)      # MW central BH
        d_g = CONSTANTS.get('d_g_sun', 2.55e20)                 # Distance to galactic center
        Omega_g = CONSTANTS.get('Omega_g_MW', 2.5e-8)           # Galactic rotation rate
        
        # Get base UQFF values
        base = self.compute_UQFF_base(t)
        Ug_sum = base['Ug1'] + base['Ug2'] + base['Ug3'] + base['Ug4']
        Ub = base['Ub']
        
        # Master buoyant integral
        galactic_factor = Omega_g * (M_bh / d_g)
        F_U_Bi_i = galactic_factor * (Ug_sum + Ub)
        
        return {
            'F_U_Bi_i': F_U_Bi_i,
            'galactic_factor': galactic_factor,
            'Omega_g': Omega_g,
            'M_bh': M_bh,
            'd_g': d_g,
            'Ug_sum': Ug_sum,
            'Ub': Ub,
            'direction': 'Outside → In',
            'scale': 'Cosmic'
        }
    
    def compute_triadic_equation(self, t=None, n_layers=26):
        """
        Compute UQFF Triadic equation (26-layer gravitational scaling).
        
        g(r,t) = Σ(i=1..26) [Ug1_i + Ug2_i + Ug3_i + Ug4_i] × Q_i × [UA]_i × [SCm]_i
        
        Full 26-dimensional polynomial gravity summation.
        
        Returns:
            dict with triadic/26-layer field values
        """
        import math
        if t is None:
            t = self.t_age
        
        # Base gravitational acceleration
        g_grav = self.compute_g_grav()
        
        # Universal gravity couplings
        k_1, k_2, k_3, k_4 = 1.5, 1.2, 0.8, 0.5
        
        # 26-layer summation
        g_triadic = 0.0
        layer_contributions = []
        
        for i in range(1, n_layers + 1):
            # Layer-dependent quantum state factor
            Q_i = 1.0 / (1 + 0.01 * i)  # Decreasing with layer
            
            # Layer-dependent UA factor
            UA_i = self.rho_vac_UA * (1 - 0.02 * i) if self.rho_vac_UA else 7.09e-36 * (1 - 0.02 * i)
            
            # Layer-dependent SCm factor
            SCm_i = self.rho_vac_SCm * (1 - 0.01 * i) if self.rho_vac_SCm else 7.09e-37 * (1 - 0.01 * i)
            
            # Phase factor for this layer
            phase = 2 * math.pi * i / n_layers
            
            # Four Ug components for this layer
            Ug1_i = k_1 * g_grav * Q_i * UA_i / 7.09e-36
            Ug2_i = k_2 * g_grav * Q_i * (1 + self.z) * math.cos(phase)
            Ug3_i = k_3 * g_grav * Q_i * math.sin(phase + 2 * math.pi * t / self.t_age) if self.t_age > 0 else 0
            Ug4_i = k_4 * g_grav * Q_i * SCm_i / 7.09e-37
            
            # Total for this layer
            g_i = (Ug1_i + Ug2_i + Ug3_i + Ug4_i) * Q_i * UA_i * SCm_i * 1e72  # Normalize
            g_triadic += g_i
            
            layer_contributions.append({
                'layer': i,
                'Q_i': Q_i,
                'UA_i': UA_i,
                'SCm_i': SCm_i,
                'g_i': g_i
            })
        
        return {
            'g_triadic': g_triadic,
            'n_layers': n_layers,
            'g_grav_base': g_grav,
            'layer_sum': sum(lc['g_i'] for lc in layer_contributions),
            'first_layer': layer_contributions[0] if layer_contributions else None,
            'last_layer': layer_contributions[-1] if layer_contributions else None
        }
    
    def compute_quadratic_equation(self, t=None):
        """
        Compute UQFF Quadratic equation (root solutions).
        
        Solves g² + b×g + c = 0 for gravitational field regimes.
        
        Returns:
            dict with quadratic solution values
        """
        import math
        if t is None:
            t = self.t_age
        
        # Get compressed and resonance values
        compressed = self.compute_compressed_equation(t)
        resonance = self.compute_resonance_equation(t)
        
        g_comp = compressed.get('g_compressed', 0)
        R_amp = resonance.get('R_amplitude', 0)
        
        # Quadratic coefficients based on UQFF field balance
        # g² - (g_comp + R_amp)g + g_comp × R_amp × correlation = 0
        a = 1.0
        b = -(g_comp + R_amp)
        c = g_comp * R_amp * 0.1  # Correlation factor
        
        # Discriminant
        discriminant = b * b - 4 * a * c
        
        # Solutions
        if discriminant >= 0:
            sqrt_disc = math.sqrt(discriminant)
            x1 = (-b + sqrt_disc) / (2 * a)
            x2 = (-b - sqrt_disc) / (2 * a)
            solution_type = 'real'
        else:
            sqrt_disc = math.sqrt(-discriminant)
            x1 = -b / (2 * a)  # Real part
            x2 = sqrt_disc / (2 * a)  # Imaginary part
            solution_type = 'complex'
        
        return {
            'x1': x1,
            'x2': x2,
            'solution_type': solution_type,
            'discriminant': discriminant,
            'a': a,
            'b': b,
            'c': c,
            'g_compressed': g_comp,
            'R_amplitude': R_amp
        }

    def validate_model(self):
        """Validate model outputs."""
        compressed = self.compute_compressed_equation()
        resonance = self.compute_resonance_equation()
        
        validations = {
            'g_grav_positive': compressed['g_grav'] > 0,
            'g_compressed_positive': compressed['g_compressed'] > 0,
            'R_amplitude_positive': resonance['R_amplitude'] > 0,
            'hubble_factor_reasonable': 1.0 <= compressed['hubble_factor'] <= 2.0
        }
        
        all_passed = all(validations.values())
        
        return {
            'validations': validations,
            'all_passed': all_passed,
            'compressed_results': compressed,
            'resonance_results': resonance
        }
    
    @staticmethod
    def run_tests():
        """Run test suite for MysticMountainModel."""
        model = MysticMountainModel()
        compressed = model.compute_compressed_equation()
        resonance = model.compute_resonance_equation()
        
        tests = []
        
        # Test 1: g_grav positive
        tests.append({
            'name': 'g_grav positive',
            'computed': compressed['g_grav'],
            'passed': compressed['g_grav'] > 0
        })
        
        # Test 2: Hubble factor reasonable
        tests.append({
            'name': 'Hubble factor',
            'computed': compressed['hubble_factor'],
            'passed': 1.0 <= compressed['hubble_factor'] <= 2.0
        })
        
        # Test 3: g_compressed positive
        tests.append({
            'name': 'g_compressed positive',
            'computed': compressed['g_compressed'],
            'passed': compressed['g_compressed'] > 0
        })
        
        # Test 4: R_amplitude positive
        tests.append({
            'name': 'R_amplitude positive',
            'computed': resonance['R_amplitude'],
            'passed': resonance['R_amplitude'] > 0
        })
        
        # Print results
        print(f"g_compressed = {compressed['g_compressed']:.4e}")
        print(f"R_amplitude = {resonance['R_amplitude']:.4e}")
        print(f"MysticMountainModel: {sum(1 for t in tests if t['passed'])}/{len(tests)} tests passed")
        for i, test in enumerate(tests):
            status = 'PASS' if test['passed'] else 'FAIL'
            print(f"Test {i+1}: {test['name']} = {test['computed']:.4e}: {status}")
        
        return {
            'tests': tests,
            'all_passed': all(t['passed'] for t in tests),
            'class': 'MysticMountainModel',
            'g_compressed': compressed['g_compressed'],
            'R_amplitude': resonance['R_amplitude']
        }

    def long_form_solution(self, r=None, t=0):
        """
        Long-form solution with complete equation display.
        Returns detailed step-by-step calculation for all UQFF equations.
        """
        import numpy as np
        G = 6.674e-11
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None:
            r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        
        # Collect all equation results
        results = {}
        steps = []
        
        # 1. UQFF Base
        uqff = self.compute_UQFF_base(r, t)
        results['UQFF_base'] = uqff
        steps.append(f"UQFF Base: F_U = G*M/r^2 = {uqff['Ug']:.6e} m/s^2")
        
        # 2. Compressed equation
        comp = self.compute_compressed_equation(r)
        results['compressed'] = comp
        steps.append(f"Compressed: g = g_N - g_H = {comp['g_compressed']:.6e} m/s^2")
        
        # 3. Resonance equation
        res = self.compute_resonance_equation(r, t)
        results['resonance'] = res
        steps.append(f"Resonance: g_res = aDPM + aExpFreq = {res['g_resonance']:.6e} m/s^2")
        
        # 4. Superconductive
        sc = self.compute_superconductive_equation()
        results['superconductive'] = sc
        steps.append(f"Superconductive: H_SCm = {sc['H_SCm']:.6f}")
        
        # 5. Buoyant equation
        buoy = self.compute_buoyant_equation(r)
        results['buoyant'] = buoy
        steps.append(f"Buoyancy: Ub = {buoy['Ub']:.6e} m/s^2")
        
        # 6. Master buoyant
        master = self.compute_master_buoyant_equation(r)
        results['master_buoyant'] = master
        steps.append(f"Master Buoyant: F_U_Bi_i = {master['F_U_Bi_i']:.6e} N")
        
        # 7. Triadic
        tri = self.compute_triadic_equation(r)
        results['triadic'] = tri
        steps.append(f"Triadic: g_triadic = {tri['g_triadic']:.6e} m/s^2")
        
        # 8. Quadratic
        quad = self.compute_quadratic_equation(r)
        results['quadratic'] = quad
        steps.append(f"Quadratic: g_quad = {quad['g_quad']:.6e} m/s^2")
        
        return {
            'model': self.__class__.__name__,
            'parameters': {'M': M, 'r': r, 't': t},
            'results': results,
            'long_form': '\n'.join(steps)
        }

    def compute_master_gravity(self, r=None, t=0, include_all=True):
        """
        Master Gravity: Complete UQFF gravity computation.
        
        g_master = g_N * (1 - Ub/g_N + Ui/g_N) * H_SCm * fTRZ
        
        Combines: Newtonian, buoyancy, inertia, superconductivity, triadic zone
        """
        import numpy as np
        G = 6.674e-11
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None:
            r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        
        # Base Newtonian gravity
        g_N = G * M / r**2
        
        # Get buoyancy correction
        buoy = self.compute_buoyant_equation(r)
        Ub = buoy['Ub']
        
        # Get superconductive coefficient
        sc = self.compute_superconductive_equation()
        H_SCm = sc['H_SCm']
        
        # Get triadic factor (default: in resonance zone)
        fTRZ = 1.0
        
        # Compute master gravity
        if g_N != 0:
            correction = 1 - Ub / g_N
        else:
            correction = 1.0
        
        g_master = g_N * correction * max(0.01, H_SCm) * fTRZ
        
        # Collect additional terms if requested
        if include_all:
            comp = self.compute_compressed_equation(r)
            res = self.compute_resonance_equation(r, t)
            tri = self.compute_triadic_equation(r)
            return {
                'g_master': g_master,
                'g_N': g_N,
                'Ub': Ub,
                'H_SCm': H_SCm,
                'fTRZ': fTRZ,
                'correction': correction,
                'g_compressed': comp['g_compressed'],
                'g_resonance': res['g_resonance'],
                'g_triadic': tri['g_triadic'],
                'equation': f"g_master = g_N * (1 - Ub/g_N) * H_SCm * fTRZ = {g_master:.6e} m/s^2"
            }
        
        return {'g_master': g_master, 'g_N': g_N}




